/* HR Hub content (modules, lessons, workflows, KPIs, templates, glossary, quiz, 24-week plan).
   Extracted 1:1 from hr-hub-full-home.html */
const D = {"mods":[{"n":1,"name":"Recruitment & Talent Acquisition","dom":"ta","purpose":"Attract, assess and select suitable candidates against approved workforce requirements while delivering a fair and respectful candidate experience.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of recruitment & talent acquisition.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Workforce demand and requisition","d":"Translate business plans into approved roles, headcount, skills, budget and hiring timelines. Confirm replacement versus new position, reporting line and approval authority."},{"t":"Job analysis and job description","d":"Identify role purpose, responsibilities, essential skills, experience, working conditions and success measures. Separate must-have criteria from desirable criteria."},{"t":"Sourcing strategy","d":"Select suitable channels such as careers pages, referrals, job boards, professional networks, campus hiring, agencies and internal mobility."},{"t":"Candidate application management","d":"Collect applications consistently, communicate process stages and maintain candidate records with appropriate access controls."},{"t":"Resume screening and shortlisting","d":"Compare evidence in a CV with job-related criteria. Avoid assumptions based on protected or irrelevant personal characteristics."},{"t":"Interview planning and structured assessment","d":"Use consistent questions, scoring rubrics, trained interviewers and documented evidence. Include technical, behavioural and role-specific assessments where appropriate."},{"t":"Selection, references and verification","d":"Consolidate interview feedback, obtain approvals and complete lawful, proportionate checks with candidate notice and consent where required."},{"t":"Offer management and joining handover","d":"Prepare approved offers, communicate terms, track acceptance and hand over to onboarding."}],"flow":["Approved manpower request","Role and job description finalised","Sourcing channels activated","Applications received and acknowledged","Screening against job criteria","Structured interviews and assessments","Selection decision and approvals","Verification and offer","Acceptance and onboarding handover"],"tpl":["Manpower requisition form","Job description template","Sourcing plan","Candidate tracker / ATS stage sheet","Resume screening scorecard","Interview evaluation form","Reference-check record","Offer approval checklist","Candidate communication templates"],"kpi":["Time to fill","Time to hire","Qualified applicant rate","Source of hire","Interview-to-offer ratio","Offer acceptance rate","Candidate withdrawal rate","New-hire quality indicators"],"assign":"Create a job description for a Junior Frontend Developer. Build a sourcing plan, screen five fictional CV summaries against objective criteria, score three structured interviews and recommend one candidate with evidence.","case":"A hiring manager wants to reject a candidate because they 'do not seem like a culture fit'. Ask for job-related evidence, use the agreed scorecard and document the decision against role criteria.","demo":"Potential demonstration areas: job creation, candidate/application capture, resume parsing or matching, shortlist workflow, interview scheduling and candidate status. Verify each function in the actual Texora AI product before recording it.","check":[{"q":"What is the strongest basis for shortlisting a candidate?","a":"Documented evidence that the candidate meets the role's job-related essential criteria, assessed consistently against the approved job description."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":2,"name":"Onboarding & Induction","dom":"ops","purpose":"Help a new employee become informed, equipped, connected and productive through a coordinated pre-joining, joining and early-tenure experience.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of onboarding & induction.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Pre-boarding","d":"Send joining instructions, document checklist, first-day agenda and contact details. Coordinate with the manager, IT, facilities and payroll."},{"t":"Joining documentation","d":"Collect and verify only necessary documents through approved secure channels. Explain why information is needed and who can access it."},{"t":"Employment terms and policy acknowledgement","d":"Explain the offer, employment terms, code of conduct, policies, working arrangements and escalation channels."},{"t":"IT and workplace readiness","d":"Arrange identity, device, software, access permissions, workspace, safety briefing and role-specific tools."},{"t":"Company and role induction","d":"Introduce mission, structure, products, customers, team, role expectations and key processes."},{"t":"Buddy and manager support","d":"Assign a buddy where appropriate, schedule manager check-ins and provide a safe route for questions."},{"t":"Probation and early performance","d":"Agree objectives, training, feedback checkpoints and documented confirmation or extension decisions under policy and law."},{"t":"Onboarding evaluation","d":"Collect new-hire feedback, identify friction and improve the onboarding experience."}],"flow":["Offer accepted","Pre-boarding checklist opened","Documents and employee data verified","IT / facilities / payroll readiness confirmed","Day-one induction","Role-specific learning plan","30 / 60 / 90-day check-ins","Probation review and confirmation decision"],"tpl":["Pre-boarding checklist","Joining form","Document acknowledgement","Policy acknowledgement","IT asset issue form","Induction schedule","Buddy plan","30-60-90 day plan","Probation review form"],"kpi":["Offer-to-join ratio","Joining readiness rate","Time to productivity","Onboarding completion rate","New-hire satisfaction","Early attrition rate","Probation review completion"],"assign":"Build a 30-60-90 day onboarding plan for a new customer support associate, including learning goals, manager check-ins, system access and evidence of readiness.","case":"A new joiner arrives but their laptop and system access are unavailable. Create an escalation path, communicate transparently and document the incident without exposing credentials.","demo":"Potential demo: employee profile creation, onboarding task checklist, document collection, acknowledgement and task assignment. Confirm actual availability before claiming automation.","check":[{"q":"Why should onboarding responsibilities be assigned before the joining date?","a":"To coordinate HR, manager, IT and facilities so that required documents, access, equipment and induction are ready on day one."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":3,"name":"HR Operations","dom":"ops","purpose":"Deliver reliable day-to-day employee services and maintain accurate, secure and traceable employee records.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of hr operations.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"HR service catalogue","d":"Define common employee services, eligibility, service channels, ownership, expected response times and escalation."},{"t":"Employee master data","d":"Maintain accurate job, reporting, location, contact, employment and organisational information with change history."},{"t":"Personnel files and records","d":"Use a documented retention schedule, role-based access, secure storage and controlled disposal."},{"t":"Employee lifecycle changes","d":"Process transfers, promotions, reporting changes, location changes and employment status updates through approvals."},{"t":"HR helpdesk and case handling","d":"Log requests, classify urgency, assign owners, protect confidentiality and close cases with clear outcomes."},{"t":"Letters and employee communications","d":"Generate standard letters from approved data and templates; review before release."},{"t":"Service quality and controls","d":"Use checklists, maker-checker review, audit trails and periodic data-quality checks."},{"t":"Vendor and stakeholder coordination","d":"Coordinate with payroll, IT, facilities, finance, benefits providers and external service partners."}],"flow":["Employee request or authorised change","Identity and eligibility validation","Case or transaction logged","Required approval obtained","Record updated in system","Employee informed","Evidence retained securely","Case closed and service metric updated"],"tpl":["Employee master data form","Employee change request","HR service request form","Personnel file index","Employee letter templates","Case closure checklist","Data correction log","Records retention schedule"],"kpi":["HR request volume","First response time","Resolution time","First-contact resolution","Data accuracy rate","Open case ageing","SLA achievement"],"assign":"Design an HR service catalogue with ten request types, owners, required inputs, approval rules, target response times and escalation paths.","case":"An employee asks HR to send their colleague's salary details. Explain the confidentiality boundary and provide the correct route for an authorised request.","demo":"Potential demo: employee records, service request intake, task routing, approval status, document generation and reporting—only if supported by the live product.","check":[{"q":"What is the purpose of role-based access to employee records?","a":"To ensure people can access only the employee information required for their authorised responsibilities."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":4,"name":"Attendance & Leave Management","dom":"ops","purpose":"Record working time and manage leave, shifts, holidays, exceptions and approvals consistently under company policy and applicable law.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of attendance & leave management.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Attendance policy and work schedules","d":"Explain workdays, shifts, breaks, weekly offs, flexible arrangements and applicable attendance rules."},{"t":"Time capture methods","d":"Understand biometric, card, web, mobile and manual attendance records, including limitations and correction controls."},{"t":"Shift and roster planning","d":"Build rosters based on operational demand, employee skills, rest requirements and approved constraints."},{"t":"Leave types and eligibility","d":"Explain available leave categories, accrual, eligibility, carry-forward and encashment as defined by policy and law."},{"t":"Leave request and approval","d":"Define request inputs, manager approval, HR review, handover and employee notification."},{"t":"Attendance exceptions","d":"Handle missed punches, late arrival, early departure, overtime, remote work and system outages."},{"t":"Payroll handoff","d":"Validate attendance and approved leave before the payroll cut-off; reconcile exceptions."},{"t":"Reporting and fairness","d":"Review absence patterns carefully and apply policies consistently without inappropriate surveillance."}],"flow":["Publish calendar and roster","Capture attendance","Identify exceptions","Employee submits correction or leave request","Manager / HR review","Approve or reject with reason","Reconcile attendance","Send approved data to payroll"],"tpl":["Attendance policy","Monthly roster","Leave application form","Leave balance report","Attendance correction form","Overtime approval form","Holiday calendar","Monthly attendance reconciliation"],"kpi":["Attendance regularisation rate","Unplanned absence rate","Leave utilisation","Overtime hours","Roster adherence","Exception closure time"],"assign":"Create a one-month shift roster for a 12-person support team and design an exception process for missed punches and unplanned leave.","case":"A biometric device fails for one shift. Define a controlled manual attendance process with supervisor verification and an audit record.","demo":"Potential demo: attendance import, leave request, approval workflow, calendar and exception reporting. Verify whether Texora offers these HRMS functions; do not infer them from other product capabilities.","check":[{"q":"Why should attendance exceptions be reconciled before payroll processing?","a":"To reduce incorrect salary inputs and ensure that approved leave, overtime and corrections are reflected accurately."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":5,"name":"Payroll Management","dom":"rew","purpose":"Convert approved employee, attendance, compensation and statutory inputs into accurate, reviewed and timely payroll outputs.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of payroll management.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Payroll operating cycle","d":"Understand cut-off dates, input owners, validation, calculation, review, approval, payment and post-payroll reconciliation."},{"t":"Salary structure","d":"Explain CTC, fixed pay, variable pay, basic pay, allowances, deductions, employer contributions and employee contributions."},{"t":"Payroll inputs","d":"Collect joining, exit, attendance, leave, increment, bonus, reimbursement and recovery inputs with approvals."},{"t":"Gross and net pay","d":"Understand gross earnings, deductions and net pay; distinguish employer cost from employee take-home pay."},{"t":"Statutory deductions and contributions","d":"Learn the concepts of provident fund, ESI, professional tax, tax withholding and other applicable items. Confirm current eligibility, rates and rules with specialists."},{"t":"Payroll calculation and validation","d":"Use controlled calculations, exception reports, sample checks and maker-checker review."},{"t":"Payslips and payment","d":"Issue payslips securely, validate bank files and confirm payment reconciliation."},{"t":"Year-end and full-and-final coordination","d":"Coordinate tax declarations, annual statements, final settlements and statutory records with qualified payroll specialists."}],"flow":["Payroll calendar and cut-off published","Inputs collected from HR / managers","Master data and attendance validated","Payroll calculated","Exceptions and sample checks reviewed","Authorised approval obtained","Payment file released securely","Payslips issued","Accounting and statutory reconciliation completed"],"tpl":["Payroll input sheet","Salary structure template","Payroll variance report","New joiner / exit input form","Reimbursement register","Payslip format","Payroll approval checklist","Full-and-final input checklist"],"kpi":["Payroll accuracy rate","On-time payroll rate","Payroll variance","Off-cycle payroll count","Unresolved payroll exceptions","Cost per employee"],"assign":"Using fictional employee data, prepare a sample payroll input and reconciliation workbook. Show gross earnings, deductions and net pay as illustrative values, and clearly mark statutory calculations as requiring current expert verification.","case":"A manager submits an increment after payroll cut-off. Identify the approval, effective date, impact, exception handling and communication required.","demo":"Demonstrate payroll only if the actual Texora product has a verified payroll module. Otherwise present a clearly labelled integration concept or a separate specialist payroll system.","check":[{"q":"What is the difference between CTC and net salary?","a":"CTC represents the employer's overall annual cost for the employee; net salary is the amount payable to the employee after applicable deductions from earnings."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":6,"name":"Compensation & Benefits","dom":"rew","purpose":"Design and administer fair, competitive and financially sustainable pay and benefits programmes.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of compensation & benefits.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Total rewards framework","d":"Understand fixed pay, variable pay, benefits, recognition, wellbeing and non-financial rewards."},{"t":"Job evaluation and grading","d":"Compare role scope, responsibility, complexity and impact to establish internal job levels."},{"t":"Market benchmarking","d":"Use reliable salary survey data, comparable roles, geography, industry and experience bands."},{"t":"Salary bands and pay positioning","d":"Create minimum, midpoint and maximum ranges and explain compa-ratio as a management indicator."},{"t":"Increments and promotion pay","d":"Apply documented criteria, budget controls and approval workflows."},{"t":"Incentives and variable pay","d":"Define eligibility, measures, thresholds, caps, payout timing and governance."},{"t":"Benefits administration","d":"Coordinate insurance, retirement-related benefits, allowances and employee support."},{"t":"Pay equity and communication","d":"Review pay differences using valid factors and communicate total rewards clearly."}],"flow":["Define reward philosophy","Evaluate and grade roles","Benchmark market data","Build pay ranges","Approve budgets and eligibility","Communicate total rewards","Review outcomes and equity","Update plan and controls"],"tpl":["Compensation philosophy","Job evaluation questionnaire","Salary band sheet","Increment recommendation form","Variable pay plan","Benefits enrolment guide","Pay equity review log"],"kpi":["Compensation cost","Range penetration","Compa-ratio","Offer competitiveness","Pay equity indicators","Benefits utilisation","Budget variance"],"assign":"Create three illustrative salary bands for junior, mid-level and senior roles. Explain the assumptions, approval controls and how a promotion recommendation would be assessed.","case":"Two employees have different pay. A manager asks HR to disclose the other employee's salary. Explain confidentiality and describe a fair internal equity review process.","demo":"Potential demo: compensation records or reward analytics only where verified. Do not imply that a recruitment or CX platform calculates payroll or benefits.","check":[{"q":"Why should salary benchmarking compare similar roles and markets?","a":"Because job scope, skills, geography and industry affect market pay; unrelated comparisons can produce misleading conclusions."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":7,"name":"Performance Management","dom":"rew","purpose":"Align individual contribution with business goals through clear expectations, regular feedback, evidence-based evaluation and development.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of performance management.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Performance philosophy and cycle","d":"Understand goal setting, ongoing check-ins, review periods, calibration and development planning."},{"t":"KRA, KPI and OKR","d":"Distinguish responsibility areas, measurable indicators and outcome-oriented objectives."},{"t":"SMART goals","d":"Create specific, measurable, achievable, relevant and time-bound goals with clear ownership."},{"t":"Continuous feedback and check-ins","d":"Hold structured conversations about progress, blockers, support and next actions."},{"t":"Performance appraisal","d":"Collect evidence, evaluate outcomes and behaviours, and document ratings consistently."},{"t":"360-degree feedback","d":"Use multiple perspectives with clear purpose, confidentiality and safeguards against popularity bias."},{"t":"Calibration and fairness","d":"Review rating consistency across teams using evidence and transparent criteria."},{"t":"Performance improvement and recognition","d":"Create support plans for gaps and recognise strong contribution fairly."}],"flow":["Set organisational and team goals","Agree individual objectives","Track progress and evidence","Conduct regular check-ins","Collect review inputs","Evaluate against agreed criteria","Calibrate and approve","Discuss outcomes and development plan"],"tpl":["Goal-setting form","KRA / KPI sheet","Monthly check-in template","Self-appraisal form","Manager review form","360-degree feedback form","Performance improvement plan","Development action plan"],"kpi":["Goal completion rate","Review completion rate","Performance distribution","Internal mobility","PIP outcomes","Employee feedback participation"],"assign":"Write three SMART objectives for a customer support associate and design a monthly manager check-in template with evidence fields.","case":"A manager gives a low rating but has no examples. Ask for documented, job-related evidence and agree a fair review process.","demo":"Potential demo: review workflows, feedback capture, scorecards and performance analytics only if verified. Otherwise use a training simulation.","check":[{"q":"What makes a KPI useful?","a":"It is relevant to an agreed outcome, clearly defined, measurable, understood by its owner and reviewed in context."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":8,"name":"Learning & Development","dom":"dev","purpose":"Identify capability gaps and deliver learning that improves employee skills, role readiness and organisational performance.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of learning & development.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Learning strategy","d":"Connect learning priorities to business goals, role requirements and workforce capability."},{"t":"Training Needs Analysis","d":"Identify gaps through performance data, manager input, employee feedback, role profiles and business changes."},{"t":"Learning objectives and design","d":"Write measurable objectives and select content, practice, delivery methods and evaluation."},{"t":"Training calendar and budget","d":"Prioritise programmes, estimate costs, schedule cohorts and manage capacity."},{"t":"Delivery methods","d":"Use classroom, virtual, self-paced, coaching, mentoring, simulations and on-the-job learning."},{"t":"Learning Management Systems","d":"Understand course catalogues, enrolment, completion, assessments, attendance and reporting."},{"t":"Training evaluation","d":"Measure reaction, learning, behaviour transfer and business outcomes where feasible."},{"t":"Career-linked development","d":"Connect skills, development plans, certifications and internal opportunities."}],"flow":["Identify business capability need","Conduct needs analysis","Define learning objectives","Design content and activities","Approve budget and calendar","Deliver learning","Assess knowledge and skill","Evaluate transfer and improve"],"tpl":["Training needs analysis form","Annual training calendar","Training nomination form","Attendance sheet","Course evaluation form","Learning plan","Training budget","Post-training impact report"],"kpi":["Training hours per employee","Completion rate","Assessment improvement","Learner satisfaction","Skill gap closure","Training cost per learner","Application of learning"],"assign":"Conduct a mini Training Needs Analysis for a 20-person support team and design a four-week communication and troubleshooting learning plan.","case":"A course receives high satisfaction scores but work performance does not improve. Investigate practice opportunities, manager reinforcement and whether the course targeted the real gap.","demo":"Potential demo: learning content, course assignment, progress tracking or knowledge assistant only if verified in Texora. Do not claim an LMS exists without product confirmation.","check":[{"q":"What is the purpose of Training Needs Analysis?","a":"To identify the difference between current capability and the capability required for effective job performance."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":9,"name":"Employee Relations","dom":"exp","purpose":"Maintain constructive workplace relationships and address concerns through fair, confidential, timely and well-documented processes.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of employee relations.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Employee relations principles","d":"Understand fairness, consistency, respect, confidentiality, non-retaliation and procedural fairness."},{"t":"Grievance intake","d":"Provide accessible reporting channels, acknowledge concerns and assess urgency and safety."},{"t":"Conflict resolution","d":"Use listening, fact-finding, mediation and agreed actions where appropriate."},{"t":"Workplace investigations","d":"Define scope, preserve relevant evidence, interview fairly and avoid conflicts of interest."},{"t":"Disciplinary processes","d":"Follow policy and applicable law, provide notice and opportunity to respond, and document decisions."},{"t":"Manager coaching","d":"Help managers communicate expectations, resolve routine issues and escalate sensitive matters."},{"t":"Harassment and safeguarding","d":"Route sensitive complaints to trained, authorised personnel and applicable statutory mechanisms."},{"t":"Case closure and learning","d":"Communicate outcomes appropriately, monitor retaliation risk and identify systemic improvements."}],"flow":["Concern raised","Acknowledge and assess immediate risk","Assign impartial case owner","Define scope and preserve evidence","Conduct fair fact-finding","Review findings and policy","Authorised decision and communication","Follow-up and close securely"],"tpl":["Grievance form","Case intake checklist","Investigation plan","Interview notes template","Conflict resolution record","Disciplinary notice template for legal review","Case outcome record","Retaliation follow-up checklist"],"kpi":["Case volume and type","Acknowledgement time","Resolution time","Repeat issue rate","Employee trust indicators","Overdue case count"],"assign":"Create a fictional grievance case file with an intake note, investigation plan, interview questions, evidence log, outcome summary and follow-up actions.","case":"An employee reports a concern about their manager and fears retaliation. Explain confidentiality limits, safe escalation, impartial handling and follow-up.","demo":"Potential demo: secure case intake, role-based routing, status tracking and reminders only if verified. Sensitive case details must never be entered into an unapproved demo environment.","check":[{"q":"Why should an employee relations investigation be impartial?","a":"To assess facts fairly, reduce conflicts of interest and support a defensible, consistent outcome."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":10,"name":"Labour Law & Compliance","dom":"gov","purpose":"Help HR identify applicable employment obligations, maintain evidence, monitor deadlines and escalate interpretation to qualified specialists.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of labour law & compliance.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Compliance governance","d":"Identify the legal entity, establishment, location, workforce categories, applicability thresholds and responsible owners."},{"t":"Employment terms and wage compliance","d":"Understand the need to verify current wage, working-time, overtime and employment-condition requirements."},{"t":"Social security concepts","d":"Understand the broad purpose of provident fund, employee insurance, gratuity and other applicable social-security obligations."},{"t":"Working conditions and safety","d":"Review working hours, leave, holidays, welfare and occupational safety requirements relevant to the establishment."},{"t":"Industrial relations","d":"Understand employee representation, standing orders, dispute handling and separation-related obligations where applicable."},{"t":"POSH and workplace protection","d":"Understand prevention, awareness, complaint channels, Internal Committee requirements and confidentiality where applicable."},{"t":"Registers, returns and notices","d":"Maintain the applicable registers, records, notices and returns using verified current formats and deadlines."},{"t":"Audit and change monitoring","d":"Maintain a compliance calendar, evidence repository, ownership matrix and periodic legal review."}],"flow":["Map legal entities and establishments","Determine applicability with counsel","Maintain obligation register","Assign owners and due dates","Collect evidence and complete actions","Review and approve filings","Retain proof and audit trail","Monitor law changes and remediate gaps"],"tpl":["Compliance applicability matrix","Compliance calendar","Statutory register index","Audit checklist","POSH awareness record","Training attendance","Evidence tracker","Legal change log"],"kpi":["On-time compliance completion","Overdue obligations","Audit findings","Corrective action closure","Training completion","Repeat non-conformities"],"assign":"Build a compliance applicability register for a fictional organisation with two locations. Mark every legal applicability item as 'to be verified by qualified counsel' until validated.","case":"A site manager asks whether a specific statutory filing is required. Identify the facts needed and escalate to the authorised compliance specialist rather than guessing.","demo":"Potential demo: compliance calendar, reminders, evidence repository and task ownership only if verified. Software reminders do not constitute legal advice or guarantee compliance.","check":[{"q":"What should HR do when applicability of a labour-law provision is uncertain?","a":"Gather establishment and workforce facts, consult qualified legal/compliance specialists and document the verified applicability decision."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":11,"name":"HR Policies & Documentation","dom":"gov","purpose":"Create clear, approved and accessible people policies and maintain controlled employment documents throughout their lifecycle.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of hr policies & documentation.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Policy governance","d":"Define policy owner, approver, scope, effective date, review cycle and version control."},{"t":"Employee handbook","d":"Organise workplace expectations, benefits, conduct, leave, working arrangements and employee support information."},{"t":"Code of conduct","d":"Explain expected behaviour, conflicts of interest, confidentiality, respectful conduct and reporting routes."},{"t":"Employment documentation","d":"Understand offer letters, appointment letters, agreements, amendments and separation documents; obtain legal review."},{"t":"Operational policies","d":"Develop leave, attendance, travel, expense, remote work, IT acceptable-use and other relevant policies."},{"t":"SOP and process documentation","d":"Describe purpose, roles, inputs, steps, controls, exceptions, records and escalation."},{"t":"Acknowledgement and communication","d":"Publish approved versions, communicate changes and record acknowledgements where appropriate."},{"t":"Document retention and review","d":"Maintain access controls, retention periods, legal holds and controlled disposal."}],"flow":["Identify policy need","Research requirements and consult stakeholders","Draft in plain language","Review with legal / functional owners","Obtain authorised approval","Publish controlled version","Communicate and acknowledge","Review on schedule and archive superseded version"],"tpl":["Policy template","Employee handbook outline","Code of conduct","SOP template","Policy approval sheet","Version history","Acknowledgement form","Policy review calendar"],"kpi":["Policy review completion","Acknowledgement rate","Policy-related queries","Exception count","Document version errors"],"assign":"Draft a plain-language remote-work policy outline with scope, eligibility, security expectations, approval, equipment, working hours and review owner. Mark it for legal and management approval.","case":"A manager circulates an old policy PDF. Explain version control, withdraw obsolete copies and direct employees to the approved source.","demo":"Potential demo: controlled document repository, acknowledgement, search and policy Q&A only if verified. Do not upload confidential employee records to public demo tools.","check":[{"q":"Why is version control important for HR policies?","a":"It helps employees and managers use the current approved policy and preserves a record of changes and effective dates."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":12,"name":"HR Analytics & HRIS","dom":"str","purpose":"Use reliable people data and fit-for-purpose systems to understand workforce patterns and support evidence-based decisions.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of hr analytics & hris.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"HRIS fundamentals","d":"Understand employee master data, organisation structures, workflows, permissions, integrations and audit trails."},{"t":"Data definitions and quality","d":"Define fields, owners, valid values, completeness, accuracy, timeliness and duplicate handling."},{"t":"HR reporting","d":"Build consistent headcount, hiring, absence, learning and turnover reports."},{"t":"People analytics questions","d":"Start with a business question and select data that can answer it appropriately."},{"t":"Attrition and retention analysis","d":"Distinguish voluntary and involuntary exits, cohort analysis, tenure patterns and limitations of correlation."},{"t":"Dashboard design","d":"Use clear labels, definitions, filters, date ranges, comparisons and accessible visualisations."},{"t":"Privacy and responsible analytics","d":"Apply data minimisation, access controls, aggregation and safeguards against unfair profiling."},{"t":"Insight communication","d":"Explain what the data shows, what it does not show and what further investigation is needed."}],"flow":["Define decision question","Identify data sources and owners","Validate data definitions and quality","Prepare analysis","Review privacy and access","Visualise and interpret","Discuss with stakeholders","Track action and outcome"],"tpl":["HR data dictionary","HRIS requirements checklist","Data quality log","Headcount report","Attrition analysis","Dashboard specification","Access matrix","Analytics insight brief"],"kpi":["Data completeness","Data accuracy","Report refresh timeliness","HRIS adoption","Dashboard usage","Issue resolution time"],"assign":"Create a fictional HR dashboard specification with headcount, hiring funnel, turnover, absence and training completion. Include definitions and data-quality checks.","case":"A dashboard shows higher attrition in one team. Do not assume the manager caused it; investigate tenure, role mix, location, hiring cohort and qualitative feedback.","demo":"Potential demo: dashboards, data export, workflow reports or AI summaries only where verified. Use synthetic or anonymised data in demonstrations.","check":[{"q":"Why should every HR dashboard metric have a definition?","a":"To ensure users interpret the measure consistently and understand its population, time period, numerator and denominator."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":13,"name":"Workforce Planning","dom":"str","purpose":"Ensure the organisation has the right workforce capacity and skills at the right time and cost.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of workforce planning.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Business strategy and workforce implications","d":"Translate growth, service, technology and operating-model plans into workforce assumptions."},{"t":"Demand forecasting","d":"Estimate roles, volumes, skills and timing using workload, productivity and business forecasts."},{"t":"Supply analysis","d":"Review current headcount, skills, attrition, retirement, internal mobility and availability."},{"t":"Gap analysis","d":"Compare demand and supply to identify shortages, surpluses and capability gaps."},{"t":"Scenario planning","d":"Model growth, flat, downturn, automation and location scenarios with explicit assumptions."},{"t":"Workforce cost and budget","d":"Estimate salary, benefits, hiring, training and transition costs."},{"t":"Build-buy-borrow decisions","d":"Compare hiring, reskilling, redeployment, contractors and outsourcing."},{"t":"Monitoring and governance","d":"Review assumptions, approvals and forecast-versus-actual results."}],"flow":["Understand business plan","Translate workload into role demand","Assess current workforce supply","Calculate skill and headcount gaps","Model options and costs","Agree workforce actions","Approve plan","Monitor and refresh forecast"],"tpl":["Workforce plan","Headcount budget","Skills inventory","Demand forecast","Scenario model","Vacancy plan","Workforce review pack"],"kpi":["Forecast accuracy","Vacancy rate","Headcount variance","Labour cost","Critical skill coverage","Internal fill rate"],"assign":"Build a simple quarterly workforce plan for a fictional 24/7 customer support team, using stated assumptions for shift coverage, leave and expected workload.","case":"A department requests ten hires but workload is falling. Ask for evidence, test productivity assumptions and compare redeployment or reskilling options.","demo":"Potential demo: headcount reporting, task automation or analytics only if verified. Workforce forecasting may require a dedicated planning tool or spreadsheet model.","check":[{"q":"What is the first step in workforce planning?","a":"Understand the business plan and translate it into workforce demand assumptions."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":14,"name":"Talent Management","dom":"dev","purpose":"Identify, develop and retain capabilities that are important to current and future organisational performance.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of talent management.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Talent philosophy","d":"Define what talent means for the organisation and avoid relying on vague labels."},{"t":"Competency frameworks","d":"Describe technical, behavioural, leadership and role-specific competencies."},{"t":"Talent identification","d":"Use performance, potential, skills evidence and role requirements with clear criteria."},{"t":"Talent reviews","d":"Facilitate structured discussions, challenge bias and document development actions."},{"t":"Retention planning","d":"Understand employee needs, career opportunity, manager quality, reward and work design."},{"t":"Internal mobility","d":"Create transparent opportunities for projects, transfers and open roles."},{"t":"Critical skills","d":"Identify scarce or business-critical skills and create development or succession plans."},{"t":"Talent programme evaluation","d":"Measure progression, readiness, retention and programme outcomes."}],"flow":["Define critical roles and capabilities","Set competency framework","Collect evidence","Conduct structured talent review","Agree development actions","Offer growth opportunities","Review retention and readiness"],"tpl":["Competency framework","Talent review template","Skills matrix","High-potential criteria","Development plan","Internal mobility policy","Retention action plan"],"kpi":["Critical skill coverage","Internal fill rate","Talent retention","Development action completion","Ready-now successor coverage"],"assign":"Create a skills matrix for a fictional 10-person IT support team and recommend three development actions based on evidence.","case":"A manager labels one employee as high potential because they are personally similar. Use transparent competency evidence and calibration to challenge bias.","demo":"Potential demo: employee skill profiles, candidate matching, talent dashboards or learning recommendations only if available and verified.","check":[{"q":"Why should talent identification use transparent criteria?","a":"To reduce bias, improve consistency and ensure development decisions are linked to relevant evidence."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":15,"name":"Career & Succession Planning","dom":"dev","purpose":"Help employees understand career opportunities while preparing the organisation for continuity in critical roles.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of career & succession planning.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Career architecture","d":"Define job families, levels, role expectations and progression paths."},{"t":"Career conversations","d":"Help employees explore strengths, interests, development needs and realistic opportunities."},{"t":"Individual development plans","d":"Translate career goals into skills, actions, timelines and support."},{"t":"Succession planning","d":"Identify critical roles, potential successors and readiness gaps."},{"t":"Leadership pipeline","d":"Build experiences, mentoring and leadership capability for future roles."},{"t":"Knowledge continuity","d":"Reduce dependency on single individuals through documentation and cross-training."},{"t":"Fair opportunity and governance","d":"Make criteria visible and avoid promising promotions or roles that are not approved."},{"t":"Review and refresh","d":"Update plans as roles, strategy and employee interests change."}],"flow":["Identify role families and critical positions","Define career paths and competencies","Hold career conversations","Create individual development plans","Assess succession risks","Provide stretch assignments and mentoring","Review readiness and continuity"],"tpl":["Career framework","Career conversation guide","Individual development plan","Succession matrix","Critical role register","Knowledge transfer plan"],"kpi":["Internal promotion rate","Internal mobility","Successor readiness","Critical role coverage","Development plan completion"],"assign":"Create a career pathway from HR Coordinator to HR Manager, identifying role competencies, experience and development milestones.","case":"An employee assumes a development plan guarantees promotion. Explain the difference between development support and a confirmed vacancy or promotion decision.","demo":"Potential demo: learning plans, employee profiles and skills dashboards only if verified; otherwise use a visual planning exercise.","check":[{"q":"What is the purpose of succession planning?","a":"To reduce continuity risk by preparing capable people for critical roles and documenting readiness gaps."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":16,"name":"Employee Engagement & Culture","dom":"exp","purpose":"Build a workplace where employees understand organisational purpose, feel heard and can contribute effectively.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of employee engagement & culture.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Engagement fundamentals","d":"Distinguish engagement, satisfaction, experience, wellbeing and culture."},{"t":"Listening strategy","d":"Use surveys, focus groups, stay interviews, exit feedback and manager conversations appropriately."},{"t":"Survey design","d":"Write neutral questions, protect anonymity where promised and explain how results will be used."},{"t":"Recognition and communication","d":"Design fair recognition and clear channels for organisational updates."},{"t":"Culture and behaviours","d":"Translate values into observable behaviours and leadership practices."},{"t":"Action planning","d":"Prioritise issues, assign owners and communicate progress after listening exercises."},{"t":"Change communication","d":"Explain what is changing, why, when, who is affected and where questions can be raised."},{"t":"Impact evaluation","d":"Review participation, sentiment trends, retention and qualitative evidence."}],"flow":["Define listening objective","Choose method and audience","Communicate purpose and privacy","Collect feedback","Analyse themes carefully","Agree actions and owners","Share 'you said, we did' update","Measure progress"],"tpl":["Engagement survey","Stay interview guide","Focus group guide","Recognition nomination form","Action plan","Town hall communication plan"],"kpi":["Survey participation","Engagement index","Action completion","Recognition participation","Retention trends","Employee feedback themes"],"assign":"Design a 10-question engagement pulse survey and a 30-day action plan for three hypothetical findings.","case":"Survey comments contain identifying details. Explain how to restrict access, aggregate themes and avoid promising anonymity if it cannot be guaranteed.","demo":"Potential demo: survey summaries, communications, feedback classification or workflow reminders only if verified. Avoid sending identifiable sensitive feedback into unapproved AI systems.","check":[{"q":"Why must organisations communicate actions after an engagement survey?","a":"To show that employee feedback was considered and to build trust through visible follow-through."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":17,"name":"Diversity, Equity & Inclusion","dom":"exp","purpose":"Create fair access, respectful experiences and inclusive practices across hiring, development, rewards and daily work.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of diversity, equity & inclusion.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"DEI concepts","d":"Understand diversity, equity, inclusion, accessibility and belonging without reducing people to stereotypes."},{"t":"Inclusive job design","d":"Use job-related criteria, accessible application routes and clear selection requirements."},{"t":"Bias awareness","d":"Recognise how assumptions can affect sourcing, interviews, performance reviews and promotion."},{"t":"Accessibility and accommodation","d":"Provide an appropriate process for discussing workplace adjustments and accessibility needs."},{"t":"Fair development and reward","d":"Review access to opportunities, feedback, recognition and progression."},{"t":"Inclusive communication","d":"Use respectful language, accessible formats and considerate meeting practices."},{"t":"Policy and reporting","d":"Explain relevant policies, complaint channels and protection from retaliation."},{"t":"Measurement and accountability","d":"Use lawful, proportionate, privacy-protective measures and focus on barriers and outcomes."}],"flow":["Review policies and workforce practices","Identify barriers","Consult affected stakeholders","Design inclusive interventions","Train decision-makers","Implement and communicate","Measure outcomes responsibly","Review and improve"],"tpl":["Inclusive hiring checklist","Accessible interview checklist","Accommodation request process","Bias-aware interview guide","DEI action plan","Accessibility review log"],"kpi":["Process accessibility","Representation indicators where lawful","Opportunity access","Accommodation response time","Inclusion survey themes"],"assign":"Review a fictional job advertisement and interview process for accessibility, unnecessary requirements and potential bias; propose improvements.","case":"A hiring panel uses a personal preference as a selection criterion. Replace it with role-related evidence and a consistent scoring method.","demo":"Potential demo: accessible content, structured forms and aggregated analytics only if verified. Sensitive demographic data must be handled under applicable law and strict access controls.","check":[{"q":"What is the difference between equality and equity in workplace practice?","a":"Equality provides the same treatment; equity considers relevant barriers and provides fair support so people can access opportunities."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":18,"name":"Health, Safety & Wellbeing","dom":"exp","purpose":"Support safe working conditions and employee wellbeing through prevention, awareness, reporting and specialist escalation.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of health, safety & wellbeing.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Safety responsibilities","d":"Understand employer, manager, employee and specialist responsibilities under applicable requirements."},{"t":"Hazard identification","d":"Recognise physical, ergonomic, environmental and work-process hazards."},{"t":"Risk assessment","d":"Assess likelihood, impact, controls and residual risk using approved methods."},{"t":"Incident and near-miss reporting","d":"Encourage prompt reporting, preserve facts and avoid blame-based assumptions."},{"t":"Emergency preparedness","d":"Understand evacuation, first aid, emergency contacts and drills as relevant to the site."},{"t":"Ergonomics and safe work","d":"Promote workstation, equipment and safe-work practices appropriate to the job."},{"t":"Wellbeing support","d":"Communicate available support, workload practices and referral routes without diagnosing employees."},{"t":"Training and review","d":"Maintain training evidence, inspect controls and close corrective actions."}],"flow":["Identify hazard or wellbeing concern","Make immediate area safe where possible","Notify authorised safety owner","Record incident or concern","Assess risk and investigate","Implement corrective controls","Communicate and train","Verify action effectiveness"],"tpl":["Hazard reporting form","Risk assessment template","Incident / near-miss report","Emergency contact sheet","Safety induction checklist","Corrective action register"],"kpi":["Incident frequency and severity","Near-miss reporting","Corrective action closure","Safety training completion","Inspection completion"],"assign":"Complete a simple workstation risk assessment for a fictional office desk and recommend practical controls.","case":"An employee reports a recurring safety hazard. Prioritise immediate risk control and escalation rather than treating the report as a routine HR query.","demo":"Potential demo: safety training records, incident task tracking or reminder workflows only if verified. Safety decisions must remain with qualified safety professionals.","check":[{"q":"What should happen first when an immediate workplace hazard is reported?","a":"Take appropriate immediate steps to protect people and notify the responsible safety personnel according to the emergency procedure."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":19,"name":"Employer Branding","dom":"ta","purpose":"Communicate an authentic employee value proposition and create a consistent candidate experience across the talent market.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of employer branding.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Employer value proposition","d":"Identify what employees genuinely value about the organisation and what it can credibly offer."},{"t":"Careers website and content","d":"Present accurate roles, culture, benefits, process stages and accessibility information."},{"t":"Recruitment marketing","d":"Plan campaigns by audience, role type, channel and measurable objective."},{"t":"Campus and early-career outreach","d":"Build transparent relationships with institutions and early-career candidates."},{"t":"Employee advocacy","d":"Enable voluntary, authentic employee stories with consent and content guidance."},{"t":"Candidate experience","d":"Review application simplicity, communication speed, interview respect and feedback."},{"t":"Reputation management","d":"Respond professionally to candidate and employee feedback without retaliation or disclosure."},{"t":"Brand measurement","d":"Measure qualified applications, conversion, engagement and candidate experience."}],"flow":["Research candidate audiences","Define authentic EVP","Create content and channel plan","Launch recruitment campaigns","Manage candidate communications","Collect feedback","Measure conversion and sentiment","Refresh employer messaging"],"tpl":["EVP worksheet","Careers page content brief","Recruitment campaign plan","Campus outreach pack","Employee story consent form","Candidate experience survey"],"kpi":["Career page conversion","Qualified applications","Source engagement","Candidate satisfaction","Offer acceptance","Campaign cost per qualified applicant"],"assign":"Create an employer-branding campaign for a fictional technology company hiring 20 graduates, including audience, message, channels and success metrics.","case":"Marketing wants to advertise a benefit that is not available to all employees. Validate the claim and publish accurate, qualified messaging.","demo":"Potential demo: AI-generated job descriptions, job posting workflows, candidate communication or content assistance only if verified in the product.","check":[{"q":"What makes an employer value proposition credible?","a":"It reflects real employee experience and offers that the organisation can consistently deliver."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":20,"name":"Exit & Offboarding","dom":"ops","purpose":"Manage employee separation respectfully while protecting continuity, assets, records, final payments and organisational learning.","intro":[],"extras":[],"outcomes":["Explain the core concepts and terminology of exit & offboarding.","Describe the standard workflow, roles, approvals and records.","Use relevant templates and basic metrics responsibly.","Identify risks, exceptions and matters requiring specialist escalation.","Complete a practical exercise and explain the evidence behind the result."],"lessons":[{"t":"Separation types and policy","d":"Understand resignation, retirement, redundancy, termination, end of contract and other applicable categories."},{"t":"Resignation receipt and acknowledgement","d":"Record the notice, confirm policy and contract requirements and communicate next steps respectfully."},{"t":"Notice period and handover","d":"Agree work transition, knowledge transfer, responsibilities and approved notice arrangements."},{"t":"Access and asset coordination","d":"Coordinate device, ID, facility and system access changes with IT and security at the correct time."},{"t":"Exit interview","d":"Gather voluntary feedback respectfully and avoid pressuring employees to disclose sensitive information."},{"t":"Clearance and final settlement","d":"Coordinate leave, expenses, recoveries, salary, benefits and statutory items with authorised payroll and legal specialists."},{"t":"Separation documents","d":"Prepare approved relieving, experience and other applicable documents after checks."},{"t":"Exit analytics and alumni relationship","d":"Identify themes, protect confidentiality and maintain professional relationships."}],"flow":["Separation request or event recorded","Eligibility and notice requirements reviewed","Manager and HR plan transition","Handover and knowledge transfer","Asset and access clearance","Payroll / benefits inputs reconciled","Authorised final settlement","Documents issued and records retained","Exit feedback analysed"],"tpl":["Resignation acknowledgement","Notice period tracker","Knowledge transfer checklist","Asset return form","Exit interview questionnaire","Clearance checklist","Full-and-final input sheet","Experience / relieving letter template"],"kpi":["Voluntary turnover","Regretted attrition","Exit reason themes","Handover completion","Clearance completion time","Final settlement timeliness"],"assign":"Build an offboarding checklist for a software engineer, including knowledge transfer, system access, asset return, payroll inputs and employee communication.","case":"An employee is leaving urgently and still has access to sensitive systems. Coordinate with IT/security under approved policy while respecting employment and legal requirements.","demo":"Potential demo: exit task checklist, document workflow, access-request coordination and case status only if verified. Actual access revocation must be performed by authorised IT/security systems.","check":[{"q":"Why must offboarding coordinate HR, payroll, IT and the manager?","a":"Because separation affects employment records, final payments, work continuity, company assets and access to systems."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Process flow diagram and a worked example.","Downloadable templates and a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to relevant modules."]},{"n":21,"name":"HR Sales & Client Hiring Solutions","dom":"sal","purpose":"Win and serve client hiring mandates by capturing the client’s requirement accurately, searching for and fulfilling it with suitable candidates, and presenting a clear, fair and approved costing proposal for the recruitment service.","intro":["<p>How this module differs from Module 01: Module 01 teaches hiring for one’s own organisation. Module 21 teaches HR sales and delivery for external clients: the learner acts as the client’s hiring partner, converts a client requirement into a search, fulfils it with qualified candidate profiles and quotes the commercial terms. Texora AI’s HR Sales module is currently under development, so product references in this module are verification-led (see the demonstration section).</p>"],"extras":[{"t":"Requirement intake: minimum information to capture","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Field</strong></th>\n<th><strong>What to capture</strong></th>\n<th><strong>Why it matters</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Client and contact</td>\n<td>Company, hiring manager, HR contact, decision-maker and approver of fees.</td>\n<td>Ensures the proposal reaches the right authority and avoids duplicate engagement.</td>\n</tr>\n<tr>\n<td>Role details</td>\n<td>Job title, number of openings, purpose of role, reporting line, replacement or new position.</td>\n<td>Defines the scope of the search and the fulfilment target.</td>\n</tr>\n<tr>\n<td>Skills and experience</td>\n<td>Must-have skills, good-to-have skills, years of experience, qualification, domain or industry.</td>\n<td>Forms the objective screening criteria.</td>\n</tr>\n<tr>\n<td>Location and work mode</td>\n<td>Work location, on-site, hybrid or remote, relocation openness.</td>\n<td>Determines the candidate pool size and feasibility.</td>\n</tr>\n<tr>\n<td>Compensation band</td>\n<td>Budget or CTC range, fixed and variable components, benefits.</td>\n<td>Checks market fit and sets the basis for percentage-based fees.</td>\n</tr>\n<tr>\n<td>Timeline</td>\n<td>Expected joining date, notice-period tolerance, interview schedule, urgency.</td>\n<td>Sets turnaround targets and priority.</td>\n</tr>\n<tr>\n<td>Selection process</td>\n<td>Number of rounds, interviewers, assessments, decision time.</td>\n<td>Allows realistic planning and follow-up of client feedback.</td>\n</tr>\n<tr>\n<td>Commercial expectations</td>\n<td>Preferred pricing model, payment terms, exclusivity, replacement period.</td>\n<td>Feeds directly into the proposal and costing.</td>\n</tr>\n</tbody>\n</table>"},{"t":"Commercial models and costing","h":"<p>Illustrative note: All percentages, rates and amounts in this module are teaching examples only. They are not Texora AI prices. Actual fees must follow the organisation’s approved pricing policy, and tax treatment must be confirmed with finance or a qualified tax professional.</p><table>\n\n<thead>\n<tr>\n<th><strong>Pricing model</strong></th>\n<th><strong>How the fee is calculated</strong></th>\n<th><strong>Best used when</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Permanent placement (contingency)</td>\n<td>Percentage of the hired candidate’s annual CTC, payable only if a candidate joins.</td>\n<td>Client wants to pay only for successful hires.</td>\n</tr>\n<tr>\n<td>Retained or exclusive search</td>\n<td>Retainer or advance fee plus balance on milestones or joining, usually with exclusivity.</td>\n<td>Senior, niche or confidential roles needing dedicated effort.</td>\n</tr>\n<tr>\n<td>Fixed fee per hire</td>\n<td>Pre-agreed flat amount per position, independent of CTC.</td>\n<td>Volume hiring of similar roles.</td>\n</tr>\n<tr>\n<td>Fee per verified profile / resume</td>\n<td>Agreed rate for each screened and verified candidate profile submitted, with a defined quality standard.</td>\n<td>Client wants a candidate pipeline and will run its own interviews.</td>\n</tr>\n<tr>\n<td>Contract staffing</td>\n<td>Monthly billing = candidate’s employment cost + statutory employer costs + management markup.</td>\n<td>Client needs temporary or project-based resources on the agency’s payroll.</td>\n</tr>\n<tr>\n<td>RPO / dedicated recruiter</td>\n<td>Monthly fee for a dedicated recruitment team or recruiter, sometimes plus per-hire fee.</td>\n<td>Client has continuous, high-volume hiring.</td>\n</tr>\n</tbody>\n</table>"},{"t":"Worked costing examples (illustrative figures)","h":"<p>Example A: Permanent placement. Role: Senior Java Developer. Annual CTC offered: ₹18,00,000. Agreed fee: 10% of annual CTC. GST of 18% is shown as an example rate and must be verified by finance.</p><table>\n\n<thead>\n<tr>\n<th><strong>Line</strong></th>\n<th><strong>Calculation</strong></th>\n<th><strong>Amount (₹)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Annual CTC of selected candidate</td>\n<td>As per offer letter</td>\n<td>18,00,000</td>\n</tr>\n<tr>\n<td>Placement fee</td>\n<td>10% of 18,00,000</td>\n<td>1,80,000</td>\n</tr>\n<tr>\n<td>GST (example rate)</td>\n<td>18% of 1,80,000</td>\n<td>32,400</td>\n</tr>\n<tr>\n<td>Total invoice value</td>\n<td>1,80,000 + 32,400</td>\n<td>2,12,400</td>\n</tr>\n</tbody>\n</table><p>Example B: Fee per verified profile / resume. Client requests 25 verified profiles for a Customer Support Executive requirement at an example rate of ₹500 per verified profile. A profile counts as verified only when identity, interest, availability, notice period and expected compensation have been confirmed and consent to share has been obtained.</p><table>\n\n<thead>\n<tr>\n<th><strong>Line</strong></th>\n<th><strong>Calculation</strong></th>\n<th><strong>Amount (₹)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Verified profiles requested</td>\n<td>25 profiles</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Profile fee</td>\n<td>25 × 500</td>\n<td>12,500</td>\n</tr>\n<tr>\n<td>GST (example rate)</td>\n<td>18% of 12,500</td>\n<td>2,250</td>\n</tr>\n<tr>\n<td>Total invoice value</td>\n<td>12,500 + 2,250</td>\n<td>14,750</td>\n</tr>\n</tbody>\n</table><p>Example C: Contract staffing. One contract resource with an example monthly employment cost of ₹50,000 (including employer-side statutory costs) and a management markup of 12%.</p><table>\n\n<thead>\n<tr>\n<th><strong>Line</strong></th>\n<th><strong>Calculation</strong></th>\n<th><strong>Amount (₹) per month</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Monthly employment cost</td>\n<td>As per payroll calculation</td>\n<td>50,000</td>\n</tr>\n<tr>\n<td>Management markup</td>\n<td>12% of 50,000</td>\n<td>6,000</td>\n</tr>\n<tr>\n<td>Billable amount before tax</td>\n<td>50,000 + 6,000</td>\n<td>56,000</td>\n</tr>\n</tbody>\n</table><p>Tax on contract staffing invoices depends on how the service is structured. Finance or a qualified tax professional must confirm the tax treatment before the proposal is issued.</p>"},{"t":"Costing and proposal checklist","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Proposal section</strong></th>\n<th><strong>Content to include</strong></th>\n<th><strong>Approval needed</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cover and summary</td>\n<td>Client name, role(s), proposal date, validity period and prepared-by details.</td>\n<td>Sales manager</td>\n</tr>\n<tr>\n<td>Understanding of requirement</td>\n<td>Summary of the confirmed hiring brief, volume, location and timeline.</td>\n<td>Delivery lead</td>\n</tr>\n<tr>\n<td>Scope of service</td>\n<td>What is included (sourcing, screening, submission, interview coordination) and what is excluded.</td>\n<td>Sales manager</td>\n</tr>\n<tr>\n<td>Process and timeline</td>\n<td>Search plan, profile submission timelines, interview and joining expectations.</td>\n<td>Delivery lead</td>\n</tr>\n<tr>\n<td>Costing table</td>\n<td>Pricing model, rate, calculation, taxes shown separately and total value.</td>\n<td>Finance / sales head</td>\n</tr>\n<tr>\n<td>Payment terms</td>\n<td>Invoice trigger, payment period, advance or retainer if any.</td>\n<td>Finance</td>\n</tr>\n<tr>\n<td>Replacement or guarantee terms</td>\n<td>Replacement period, conditions and exclusions if a hired candidate leaves.</td>\n<td>Sales head / legal</td>\n</tr>\n<tr>\n<td>Assumptions and conditions</td>\n<td>Budget band, feedback turnaround from client, exclusivity, confidentiality and data-protection commitments.</td>\n<td>Legal where needed</td>\n</tr>\n<tr>\n<td>Acceptance</td>\n<td>Authorised signatory, date and next steps.</td>\n<td>Client and sales manager</td>\n</tr>\n</tbody>\n</table>"},{"t":"Governance, privacy and risk controls","h":"<ul>\n<li><p>Share a candidate’s profile with a client only after obtaining the candidate’s consent and confirming the role and client are named to them.</p></li>\n<li><p>Do not submit the same candidate to the same client through multiple routes, and record the submission date to protect fee eligibility.</p></li>\n<li><p>Use accurate, verified information in candidate summaries; do not inflate experience, compensation or notice-period details.</p></li>\n<li><p>Follow applicable laws and the organisation’s policy on candidate fees; do not charge candidates unless law and policy expressly permit it. Escalate any doubt to legal.</p></li>\n<li><p>Store resumes and client requirements securely with role-based access, and follow the applicable data-protection and retention requirements.</p></li>\n<li><p>Do not promise results that cannot be guaranteed, and do not give discounts beyond approved authority.</p></li>\n<li><p>AI matching and ranking outputs support the recruiter’s judgement; a responsible person reviews every shortlist and proposal before it is sent.</p></li>\n</ul>"}],"outcomes":["Explain the HR sales cycle: lead, discovery, requirement capture, proposal, agreement, delivery, invoice handover and account growth.","Capture a client hiring requirement in a structured brief and confirm it with the client before starting the search.","Plan and run a candidate search against the requirement, and screen and submit candidate profiles with documented evidence and consent.","Track requirement fulfilment through submission, client feedback, interviews, offer and joining against agreed timelines.","Prepare a costing and proposal for the client (per placement, per profile/resume, retainer or contract staffing) and explain how every figure is derived.","Identify commercial, data-privacy and contractual risks that need escalation to sales leadership, finance or legal."],"lessons":[{"t":"Understanding the HR sales model","d":"Learn how staffing and recruitment-service businesses earn revenue, the difference between permanent placement, contract staffing, profile supply and RPO, and the roles of business development, recruiters, delivery managers and finance."},{"t":"Lead generation and client qualification","d":"Identify target companies and hiring managers, qualify leads on hiring volume, role types, budget authority and urgency, and record each lead consistently in the CRM or sales tracker."},{"t":"Client discovery and requirement intake","d":"Run a structured discovery call. Capture role title, number of openings, skills, experience range, location, work mode, budget or CTC band, notice-period tolerance, hiring timeline, interview process and the reason the role is open."},{"t":"Requirement analysis and hiring brief","d":"Convert raw client input into a clear hiring brief that separates must-have from good-to-have criteria, flags unrealistic expectations (for example, budget versus market) and is confirmed in writing by the client before work starts."},{"t":"Candidate search and sourcing for the requirement","d":"Search the internal talent pool, ATS and approved external channels using skills, titles, location and experience filters. Use AI-assisted matching only as decision support, and keep the recruiter accountable for the shortlist."},{"t":"Screening, qualification and profile submission","d":"Screen candidates against the brief, verify interest, availability, current and expected compensation and notice period, obtain consent to share the profile with the named client, and submit a concise, accurate candidate summary with the resume."},{"t":"Requirement fulfilment tracking","d":"Track each requirement through stages: sourced, screened, submitted, client feedback, interview rounds, offer, acceptance and joining. Maintain turnaround targets, client feedback loops and a clear status view for the client."},{"t":"Commercial models and costing","d":"Understand pricing models and how they are calculated: percentage-of-annual-CTC placement fee, fixed fee per hire, fee per verified profile/resume, retainer or advance, and contract-staffing monthly billing with a management markup."},{"t":"Proposal and quotation preparation","d":"Prepare a client-ready proposal containing understanding of the requirement, scope, process and timelines, costing table, payment terms, replacement or guarantee terms, assumptions and validity period, with internal approval before it is sent."},{"t":"Negotiation, agreement and handover to finance","d":"Handle discount requests and scope changes within approved limits, convert the accepted proposal into an agreement with legal and finance review, and hand over invoicing triggers (for example, candidate joining date) to finance."},{"t":"Account management and renewal","d":"Review delivery performance, collect client feedback, manage replacement requests, report on fulfilment and plan repeat mandates and upsell opportunities."}],"flow":["Lead identified and qualified","Discovery call and requirement intake","Hiring brief prepared and confirmed by client","Costing prepared and internally approved","Proposal issued, negotiated and accepted","Agreement signed and requirement opened","Candidate search and sourcing against the brief","Screening, verification and consent","Profile submission to client","Client feedback, interviews and selection","Offer, acceptance and joining tracked","Invoice trigger handed to finance","Account review, replacement support and renewal"],"tpl":["Lead and client qualification sheet","Client requirement intake form","Hiring brief and requirement confirmation note","Candidate search plan and sourcing tracker","Candidate screening and submission format","Candidate consent and right-to-represent record","Requirement fulfilment tracker","Costing calculator and pricing approval note","Client proposal and quotation template","Service agreement checklist","Invoice handover note","Client feedback and account review report"],"kpi":["Lead-to-proposal ratio","Proposal-to-win ratio","Requirement-to-submission time","Profiles submitted per opening","Submission-to-interview ratio","Interview-to-offer ratio","Offer acceptance rate","Requirement fulfilment rate","Time to fill","Fee realisation versus quoted fee","Candidate drop-off before joining","Replacement rate within the guarantee period","Client satisfaction score","Repeat mandate rate"],"assign":"A fictional client, “BrightPath Retail”, needs 3 Customer Support Executives and 1 Senior Java Developer. Complete the requirement intake form, write the hiring brief, build a search plan, screen five fictional CV summaries per role against the brief, and prepare a costing and proposal that uses one placement-fee model for the developer role and a per-verified-profile model for the support executives. Show every calculation and list the assumptions.","case":"A client asks for a developer with a very wide skill set at a budget well below market and wants the proposal “by tonight”. A colleague suggests accepting everything to win the mandate. Discuss how to clarify the requirement, explain the market gap with evidence, offer realistic options (adjusted budget, phased scope or a different model) and avoid promising what cannot be delivered.","demo":"The HR Sales module is currently under development in Texora AI. Potential demonstration areas, to be recorded only after each function is confirmed in the live product: client and requirement capture, candidate search and matching against a requirement, shortlist and profile submission, requirement fulfilment status tracking, and costing or proposal preparation for the client. Use synthetic client and candidate data, label any concept screens clearly, and obtain product-owner approval before publishing.","check":[{"q":"Why must a client requirement be confirmed in writing before the candidate search begins?","a":"A confirmed hiring brief removes ambiguity about must-have criteria, budget, timeline and volume, prevents wasted sourcing and disputes later, and gives an objective basis for screening, fulfilment tracking and the costing proposal."},{"q":"A client asks for a quote for 40 verified profiles. What must the proposal clearly define?","a":"The meaning of a verified profile, the rate and calculation, taxes shown separately, timeline, candidate-consent and data-handling conditions, exclusions and the validity period of the quote."}],"elem":["Module introduction video and estimated learning time.","Topic navigation with lesson completion indicators.","Requirement intake form walkthrough and a sample completed hiring brief.","Interactive costing calculator exercise with the three worked examples.","Downloadable proposal and quotation template with a sample completed version.","Scenario activity, knowledge check and assessment.","Related glossary terms and links to Modules 01, 05, 06, 10 and 19."]}],"pages":{"1":{"title":"Programme Overview and Learning Architecture","intro":"","subs":[{"t":"1.1 Programme purpose","h":"<p>The programme teaches learners how HR contributes to business performance throughout the employee lifecycle—from workforce planning and attracting candidates to onboarding, development, rewards, employee relations and offboarding. It combines HR fundamentals, operational workflows, practical documents, case studies, assessments and verified software demonstrations.</p>"},{"t":"1.2 Intended learners","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Learner group</strong></th>\n<th><strong>Learning emphasis</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>HR beginners and freshers</td>\n<td>Understand HR terminology, routine processes, documentation and professional communication.</td>\n</tr>\n<tr>\n<td>HR students and job seekers</td>\n<td>Connect academic concepts with realistic workplace tasks and portfolio projects.</td>\n</tr>\n<tr>\n<td>HR executives and coordinators</td>\n<td>Improve process execution, records, service quality and compliance awareness.</td>\n</tr>\n<tr>\n<td>HR managers and business partners</td>\n<td>Use workforce data, policies, performance practices and people strategy to support decisions.</td>\n</tr>\n<tr>\n<td>Corporate teams</td>\n<td>Build consistent understanding of employee lifecycle processes and internal HR systems.</td>\n</tr>\n</tbody>\n</table>"},{"t":"1.3 Learning outcomes","h":"<ul>\n<li><p>Explain the purpose, scope and operating model of an HR function.</p></li>\n<li><p>Map the employee lifecycle and identify process owners, approvals and records.</p></li>\n<li><p>Prepare common HR documents using approved templates and controlled data.</p></li>\n<li><p>Apply fair, consistent and documented approaches to hiring, performance, employee relations and exits.</p></li>\n<li><p>Interpret basic HR metrics and communicate insights without overstating what the data proves.</p></li>\n<li><p>Recognise when a matter requires escalation to HR leadership, legal, payroll, finance, IT or occupational safety specialists.</p></li>\n<li><p>Demonstrate HR workflows in software only where the capability is available and verified.</p></li>\n<li><p>Complete a practical HR portfolio project and pass module assessments.</p></li>\n</ul>"},{"t":"1.4 Recommended learning model","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Learning component</strong></th>\n<th><strong>Recommended share</strong></th>\n<th><strong>What it includes</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Concept learning</td>\n<td>25%</td>\n<td>Short lessons, terminology, frameworks and instructor explanations.</td>\n</tr>\n<tr>\n<td>Process demonstrations</td>\n<td>15%</td>\n<td>Flowcharts, screen walkthroughs and worked examples.</td>\n</tr>\n<tr>\n<td>Practical work</td>\n<td>35%</td>\n<td>Templates, role plays, case studies, simulations and assignments.</td>\n</tr>\n<tr>\n<td>Assessment and feedback</td>\n<td>15%</td>\n<td>Quizzes, scenario questions, rubric-based evaluation.</td>\n</tr>\n<tr>\n<td>Reflection and portfolio</td>\n<td>10%</td>\n<td>Learning journal, evidence, improvement plan and capstone.</td>\n</tr>\n</tbody>\n</table>"},{"t":"1.5 Standard learner journey","h":"<ol type=\"1\">\n<li><p>Orientation and baseline knowledge check</p></li>\n<li><p>Choose a module or follow the 24-week pathway</p></li>\n<li><p>Complete lessons in sequence</p></li>\n<li><p>Review a process map and worked example</p></li>\n<li><p>Complete a practical assignment</p></li>\n<li><p>Submit module assessment</p></li>\n<li><p>Review feedback and remediate gaps</p></li>\n<li><p>Explore the relevant verified product demonstration</p></li>\n<li><p>Save evidence to the learner portfolio</p></li>\n<li><p>Complete capstone and final evaluation</p></li>\n</ol>"}]},"2":{"title":"Complete HR Function Classification","intro":"<p>HR is not a single activity. It is a coordinated set of people, policy, operational, analytical and strategic functions. Organisations may combine or rename teams depending on size and industry.</p><table>\n\n<thead>\n<tr>\n<th><strong>HR domain</strong></th>\n<th><strong>Primary purpose</strong></th>\n<th><strong>Modules</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Talent acquisition</td>\n<td>Plan roles, attract candidates, assess and hire.</td>\n<td>01, 19</td>\n</tr>\n<tr>\n<td>Employee lifecycle operations</td>\n<td>Administer joining, records, attendance, service requests and exits.</td>\n<td>02, 03, 04, 20</td>\n</tr>\n<tr>\n<td>HR sales and client solutions</td>\n<td>Win client hiring requirements, fulfil them with candidates and price proposals for the service.</td>\n<td>21</td>\n</tr>\n<tr>\n<td>Reward and performance</td>\n<td>Manage pay, benefits, goals, feedback and performance outcomes.</td>\n<td>05, 06, 07</td>\n</tr>\n<tr>\n<td>People development</td>\n<td>Build skills, careers, leadership and organisational capability.</td>\n<td>08, 14, 15</td>\n</tr>\n<tr>\n<td>Employee experience and relations</td>\n<td>Support engagement, culture, fairness, inclusion and wellbeing.</td>\n<td>09, 16, 17, 18</td>\n</tr>\n<tr>\n<td>Governance and policy</td>\n<td>Maintain policies, legal compliance, controls and records.</td>\n<td>10, 11</td>\n</tr>\n<tr>\n<td>People strategy and intelligence</td>\n<td>Forecast workforce needs and turn HR data into decisions.</td>\n<td>12, 13</td>\n</tr>\n</tbody>\n</table>","subs":[{"t":"2.1 HR operating model","h":"<ul>\n<li><p>Business leaders define business priorities, workforce needs and role expectations.</p></li>\n<li><p>HR leadership sets people strategy, policies, service standards and governance.</p></li>\n<li><p>HR specialists own specialist processes such as recruitment, rewards, learning and employee relations.</p></li>\n<li><p>HR operations provides employee services, records, workflow coordination and reporting.</p></li>\n<li><p>Managers carry out day-to-day people leadership, feedback, approvals and performance conversations.</p></li>\n<li><p>Employees use approved channels to access information, request services and fulfil their responsibilities.</p></li>\n<li><p>Technology supports workflows, records, reminders and reporting; it does not replace human accountability.</p></li>\n</ul>"}]},"4":{"title":"Cross-Functional HR Processes and Employee Lifecycle","intro":"","subs":[{"t":"4.1 Employee lifecycle map","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Lifecycle stage</strong></th>\n<th><strong>Core HR activity</strong></th>\n<th><strong>Main partner teams</strong></th>\n<th><strong>Evidence / output</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Plan</td>\n<td>Workforce planning and approved requisition</td>\n<td>Business, Finance</td>\n<td>Headcount plan, requisition</td>\n</tr>\n<tr>\n<td>Attract</td>\n<td>Employer brand, sourcing and recruitment</td>\n<td>Hiring manager, Marketing</td>\n<td>Candidate pipeline, interview records</td>\n</tr>\n<tr>\n<td>Select</td>\n<td>Assessment, verification and offer</td>\n<td>Hiring manager, Legal where needed</td>\n<td>Selection decision, approved offer</td>\n</tr>\n<tr>\n<td>Join</td>\n<td>Onboarding, induction and access readiness</td>\n<td>IT, Facilities, Payroll</td>\n<td>Employee record, induction checklist</td>\n</tr>\n<tr>\n<td>Operate</td>\n<td>HR services, attendance, leave and payroll inputs</td>\n<td>Managers, Finance, IT</td>\n<td>Employee records, time and payroll inputs</td>\n</tr>\n<tr>\n<td>Grow</td>\n<td>Learning, performance, career and talent</td>\n<td>Managers, L&amp;D</td>\n<td>Goals, reviews, development plans</td>\n</tr>\n<tr>\n<td>Engage</td>\n<td>Culture, listening, relations and wellbeing</td>\n<td>Leaders, Safety, Employee representatives</td>\n<td>Action plans, case records</td>\n</tr>\n<tr>\n<td>Reward</td>\n<td>Compensation, benefits and recognition</td>\n<td>Finance, Payroll</td>\n<td>Approved reward decisions</td>\n</tr>\n<tr>\n<td>Exit</td>\n<td>Offboarding, handover and final settlement</td>\n<td>Manager, IT, Payroll, Legal</td>\n<td>Clearance, settlement inputs, exit feedback</td>\n</tr>\n</tbody>\n</table>"},{"t":"4.2 Process control principles","h":"<ul>\n<li><p>Every process has a named owner and an approved procedure.</p></li>\n<li><p>Inputs are defined, validated and collected through secure channels.</p></li>\n<li><p>Approvals are separated from preparation where the risk warrants maker-checker control.</p></li>\n<li><p>Exceptions are logged, assigned and resolved with evidence.</p></li>\n<li><p>Employees receive clear status updates and know where to ask for help.</p></li>\n<li><p>Sensitive records are accessible only to authorised roles.</p></li>\n<li><p>Templates have owners, version numbers, effective dates and review dates.</p></li>\n<li><p>Metrics have definitions, data owners and reporting periods.</p></li>\n<li><p>Automation is tested, monitored and supported by a manual contingency route.</p></li>\n<li><p>Human decision-makers remain accountable for employment decisions.</p></li>\n</ul>"}]},"5":{"title":"24-Week Training Roadmap","intro":"<p>The existing HTML used a 24-week learning journey. The expanded roadmap below retains that duration and distributes all 21 modules across four stages. Trainers may adjust the pace for shorter bootcamps or corporate cohorts.</p>","subs":[{"t":"Stage 1 — HR Foundations (Weeks 1–6)","h":"<ul>\n<li><p>Week 1: HR fundamentals, employee lifecycle and HR operating model</p></li>\n<li><p>Week 2: Module 01 Recruitment &amp; Talent Acquisition</p></li>\n<li><p>Week 3: Module 02 Onboarding &amp; Induction</p></li>\n<li><p>Week 4: Module 03 HR Operations</p></li>\n<li><p>Week 5: Module 04 Attendance &amp; Leave</p></li>\n<li><p>Week 6: Module 11 HR Policies &amp; Documentation</p></li>\n</ul>"},{"t":"Stage 2 — Rewards and Governance (Weeks 7–12)","h":"<ul>\n<li><p>Week 7: Module 05 Payroll Management</p></li>\n<li><p>Week 8: Module 06 Compensation &amp; Benefits</p></li>\n<li><p>Week 9: Module 10 Labour Law &amp; Compliance</p></li>\n<li><p>Week 10: Payroll and compliance case study</p></li>\n<li><p>Week 11: Module 20 Exit &amp; Offboarding</p></li>\n<li><p>Week 12: Stage assessment and portfolio review</p></li>\n</ul>"},{"t":"Stage 3 — People Growth and Experience (Weeks 13–18)","h":"<ul>\n<li><p>Week 13: Module 07 Performance Management</p></li>\n<li><p>Week 14: Module 08 Learning &amp; Development</p></li>\n<li><p>Week 15: Module 14 Talent Management</p></li>\n<li><p>Week 16: Module 15 Career &amp; Succession Planning</p></li>\n<li><p>Week 17: Module 16 Employee Engagement &amp; Culture</p></li>\n<li><p>Week 18: Modules 09 Employee Relations and 17 DEI</p></li>\n</ul>"},{"t":"Stage 4 — Strategy, Data and Application (Weeks 19–24)","h":"<ul>\n<li><p>Week 19: Module 18 Health, Safety &amp; Wellbeing</p></li>\n<li><p>Week 20: Modules 19 Employer Branding and 21 HR Sales &amp; Client Hiring Solutions</p></li>\n<li><p>Week 21: Module 12 HR Analytics &amp; HRIS</p></li>\n<li><p>Week 22: Module 13 Workforce Planning</p></li>\n<li><p>Week 23: Integrated capstone and Texora AI product demonstrations</p></li>\n<li><p>Week 24: Final assessment, presentation and portfolio submission</p></li>\n</ul>"},{"t":"5.1 Weekly learner rhythm","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Day / activity</strong></th>\n<th><strong>Suggested work</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Day 1</td>\n<td>Instructor introduction, learning objectives and core concepts.</td>\n</tr>\n<tr>\n<td>Day 2</td>\n<td>Detailed lessons, terminology and process map.</td>\n</tr>\n<tr>\n<td>Day 3</td>\n<td>Worked example, video demonstration and guided practice.</td>\n</tr>\n<tr>\n<td>Day 4</td>\n<td>Individual or group assignment using approved templates.</td>\n</tr>\n<tr>\n<td>Day 5</td>\n<td>Knowledge check, feedback, reflection and portfolio update.</td>\n</tr>\n</tbody>\n</table>"},{"t":"5.2 Suggested time commitment","h":"<p>Suggested baseline: 4–6 hours per week for self-paced learners, plus optional instructor-led sessions. Corporate programmes may use workshops and workplace projects. Adjust based on learner experience and the depth of practical assessment.</p>"}]},"6":{"title":"Training Delivery and Lesson Page Blueprint","intro":"","subs":[{"t":"6.1 Standard module overview page","h":"<ul>\n<li><p>Module title, one-line value proposition and relevant hero visual</p></li>\n<li><p>Module purpose, audience, prerequisites and estimated duration</p></li>\n<li><p>Learning outcomes and skills gained</p></li>\n<li><p>Module classification and lesson list</p></li>\n<li><p>Process lifecycle diagram</p></li>\n<li><p>Beginner / Intermediate / Advanced learning levels</p></li>\n<li><p>Practical assignment and expected evidence</p></li>\n<li><p>Document and video library</p></li>\n<li><p>Assessment status and completion criteria</p></li>\n<li><p>Related modules and verified product demonstration</p></li>\n</ul>"},{"t":"6.2 Standard lesson page","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Section</strong></th>\n<th><strong>Required content</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Lesson header</td>\n<td>Title, module, level, duration, last updated and trainer.</td>\n</tr>\n<tr>\n<td>Why it matters</td>\n<td>Business context and practical relevance.</td>\n</tr>\n<tr>\n<td>Learning objectives</td>\n<td>Three to five measurable objectives.</td>\n</tr>\n<tr>\n<td>Core explanation</td>\n<td>Definitions, concepts, examples, decision rules and limitations.</td>\n</tr>\n<tr>\n<td>Process walkthrough</td>\n<td>Steps, role owners, approvals, inputs and outputs.</td>\n</tr>\n<tr>\n<td>Worked example</td>\n<td>Fictional example with explanation and result.</td>\n</tr>\n<tr>\n<td>Visual learning</td>\n<td>Diagram, infographic, comparison table or short video.</td>\n</tr>\n<tr>\n<td>Common mistakes</td>\n<td>Typical errors, consequences and prevention.</td>\n</tr>\n<tr>\n<td>Practice task</td>\n<td>Action the learner must complete.</td>\n</tr>\n<tr>\n<td>Knowledge check</td>\n<td>Questions with explanations, not only a pass/fail score.</td>\n</tr>\n<tr>\n<td>Resources</td>\n<td>Templates, glossary, policy references and further reading.</td>\n</tr>\n<tr>\n<td>Completion</td>\n<td>Mark complete after required activity and assessment conditions.</td>\n</tr>\n</tbody>\n</table>"},{"t":"6.3 Content depth standards","h":"<ul>\n<li><p>Avoid pages that contain only a heading, three generic bullets and a decorative image.</p></li>\n<li><p>Every lesson must explain what the concept means, why it matters, how the process works and what evidence is produced.</p></li>\n<li><p>Use realistic examples but fictionalise personal data and company information.</p></li>\n<li><p>Show a completed example alongside a blank template.</p></li>\n<li><p>Add diagrams for processes, decision trees for exceptions and charts for data topics.</p></li>\n<li><p>Separate verified product capabilities from proposed workflows or conceptual mockups.</p></li>\n</ul>"},{"t":"6.4 Video learning specification","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Video type</strong></th>\n<th><strong>Recommended length</strong></th>\n<th><strong>Content</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Module introduction</td>\n<td>2–4 minutes</td>\n<td>What the function does and what learners will achieve.</td>\n</tr>\n<tr>\n<td>Concept lesson</td>\n<td>4–8 minutes</td>\n<td>One concept with examples and visual explanation.</td>\n</tr>\n<tr>\n<td>Process walkthrough</td>\n<td>5–10 minutes</td>\n<td>Step-by-step workflow and roles.</td>\n</tr>\n<tr>\n<td>Product demonstration</td>\n<td>3–8 minutes</td>\n<td>Actual product task, screen capture and narration.</td>\n</tr>\n<tr>\n<td>Case study</td>\n<td>5–12 minutes</td>\n<td>Scenario, decisions, outcome and reflection.</td>\n</tr>\n</tbody>\n</table>"}]},"7":{"title":"Practical Assignments and Capstone Projects","intro":"","subs":[{"t":"7.1 Assignment types","h":"<ul>\n<li><p>Document creation: prepare a job description, policy outline, checklist or review form.</p></li>\n<li><p>Process mapping: draw a workflow with inputs, owners, approvals, exceptions and outputs.</p></li>\n<li><p>Role play: conduct a structured interview, onboarding conversation or grievance intake simulation.</p></li>\n<li><p>Data exercise: analyse fictional headcount, hiring, attendance or turnover data.</p></li>\n<li><p>Case study: assess a workplace scenario and recommend a fair, documented response.</p></li>\n<li><p>Software demonstration: complete a verified workflow using a sandbox or synthetic dataset.</p></li>\n</ul>"},{"t":"7.2 Capstone project A — Build an HR operating model for a 50-person company","h":"<p>Scenario: A fictional growing company has 50 employees across two locations and plans to hire 20 more people. Learners must design a practical HR operating model.</p><ol type=\"1\">\n<li><p>Create an organisation chart and role ownership matrix.</p></li>\n<li><p>Prepare a manpower plan and three sample job descriptions.</p></li>\n<li><p>Design recruitment, selection and onboarding workflows.</p></li>\n<li><p>Create employee master data fields and access roles.</p></li>\n<li><p>Prepare attendance, leave and payroll input controls.</p></li>\n<li><p>Draft an HR policy index and compliance applicability register for specialist review.</p></li>\n<li><p>Design performance and learning cycles.</p></li>\n<li><p>Build a basic HR dashboard specification.</p></li>\n<li><p>Prepare an offboarding checklist.</p></li>\n<li><p>Present risks, assumptions and a 90-day implementation plan.</p></li>\n</ol>"},{"t":"7.3 Capstone project B — Recruitment-to-joining simulation","h":"<ol type=\"1\">\n<li><p>Receive an approved requisition.</p></li>\n<li><p>Write a job description and sourcing plan.</p></li>\n<li><p>Review fictional candidate profiles using a scorecard.</p></li>\n<li><p>Conduct a structured interview simulation.</p></li>\n<li><p>Prepare a selection recommendation and offer checklist.</p></li>\n<li><p>Create the new-hire pre-boarding and first-30-day plan.</p></li>\n<li><p>Demonstrate relevant verified Texora AI recruitment workflows, if available.</p></li>\n</ol>"},{"t":"7.4 Capstone project C — HR analytics case","h":"<ol type=\"1\">\n<li><p>Use a synthetic dataset with employee ID codes, department, location, tenure, hiring date and exit date.</p></li>\n<li><p>Define headcount, turnover and hiring metrics precisely.</p></li>\n<li><p>Clean missing and duplicate data.</p></li>\n<li><p>Build a dashboard with filters and date range.</p></li>\n<li><p>Identify patterns without making unsupported causal claims.</p></li>\n<li><p>Write three recommendations and identify what further data is needed.</p></li>\n</ol>"},{"t":"7.5 Capstone evaluation rubric","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Criterion</strong></th>\n<th><strong>Weight</strong></th>\n<th><strong>Evidence</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>HR concept accuracy</td>\n<td>20%</td>\n<td>Correct use of terminology, process and policy concepts.</td>\n</tr>\n<tr>\n<td>Process design</td>\n<td>20%</td>\n<td>Clear steps, roles, approvals, exceptions and handoffs.</td>\n</tr>\n<tr>\n<td>Documentation quality</td>\n<td>15%</td>\n<td>Complete, readable, versioned and appropriately controlled records.</td>\n</tr>\n<tr>\n<td>Practical execution</td>\n<td>20%</td>\n<td>Evidence of completing the task and handling exceptions.</td>\n</tr>\n<tr>\n<td>Data and analysis</td>\n<td>10%</td>\n<td>Correct definitions, calculations and cautious interpretation.</td>\n</tr>\n<tr>\n<td>Communication and ethics</td>\n<td>15%</td>\n<td>Clear presentation, confidentiality and fair decision-making.</td>\n</tr>\n</tbody>\n</table>"}]},"9":{"title":"Assessment, Certification and Evaluation","intro":"","subs":[{"t":"9.1 Assessment types","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Assessment</strong></th>\n<th><strong>Purpose</strong></th>\n<th><strong>Example</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Knowledge quiz</td>\n<td>Check terminology and core concepts.</td>\n<td>MCQ, true/false and matching.</td>\n</tr>\n<tr>\n<td>Scenario assessment</td>\n<td>Evaluate judgement and process application.</td>\n<td>Respond to a grievance or payroll exception.</td>\n</tr>\n<tr>\n<td>Practical assignment</td>\n<td>Check the ability to produce work.</td>\n<td>Complete a job description and scorecard.</td>\n</tr>\n<tr>\n<td>Role play</td>\n<td>Observe communication and interpersonal skill.</td>\n<td>Structured interview or onboarding conversation.</td>\n</tr>\n<tr>\n<td>Capstone</td>\n<td>Evaluate integrated understanding.</td>\n<td>Design a complete HR operating model.</td>\n</tr>\n</tbody>\n</table>"},{"t":"9.2 Suggested scoring model","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Component</strong></th>\n<th><strong>Weight</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Module knowledge quiz</td>\n<td>20%</td>\n</tr>\n<tr>\n<td>Practical assignment</td>\n<td>35%</td>\n</tr>\n<tr>\n<td>Scenario / case study</td>\n<td>20%</td>\n</tr>\n<tr>\n<td>Participation and reflection</td>\n<td>5%</td>\n</tr>\n<tr>\n<td>Final capstone</td>\n<td>20%</td>\n</tr>\n</tbody>\n</table><p>Suggested pass threshold: 70% overall, with mandatory completion of required practical work. Organisations may set different thresholds. Learners who do not pass should receive feedback, targeted revision and a reassessment opportunity.</p>"},{"t":"9.3 Sample questions","h":"<p><strong>1. Recruitment:</strong> Which method best supports a consistent interview decision?</p><blockquote>\n<p><strong>Answer guide:</strong> A structured interview with job-related questions and a common scoring rubric.</p>\n</blockquote><p><strong>2. Onboarding:</strong> Which teams should coordinate first-day readiness?</p><blockquote>\n<p><strong>Answer guide:</strong> HR, the hiring manager, IT and facilities, as relevant.</p>\n</blockquote><p><strong>3. HR Operations:</strong> Why restrict access to personnel records?</p><blockquote>\n<p><strong>Answer guide:</strong> To protect employee privacy and limit access to authorised business needs.</p>\n</blockquote><p><strong>4. Attendance:</strong> What should happen when an attendance record is disputed?</p><blockquote>\n<p><strong>Answer guide:</strong> Validate evidence, follow the correction process and retain the approval trail.</p>\n</blockquote><p><strong>5. Payroll:</strong> What should be done before releasing payroll?</p><blockquote>\n<p><strong>Answer guide:</strong> Validate inputs, review exceptions, obtain approval and reconcile outputs.</p>\n</blockquote><p><strong>6. Performance:</strong> What makes a performance goal useful?</p><blockquote>\n<p><strong>Answer guide:</strong> A clear outcome, measure, owner, timeframe and agreed expectations.</p>\n</blockquote><p><strong>7. Learning:</strong> What does Training Needs Analysis identify?</p><blockquote>\n<p><strong>Answer guide:</strong> The gap between current capability and required capability.</p>\n</blockquote><p><strong>8. Employee Relations:</strong> What is important in a grievance investigation?</p><blockquote>\n<p><strong>Answer guide:</strong> Impartiality, confidentiality, evidence, fairness and appropriate escalation.</p>\n</blockquote><p><strong>9. Compliance:</strong> What if legal applicability is unclear?</p><blockquote>\n<p><strong>Answer guide:</strong> Obtain qualified legal/compliance review and document the verified decision.</p>\n</blockquote><p><strong>10. Analytics:</strong> What should accompany a dashboard metric?</p><blockquote>\n<p><strong>Answer guide:</strong> A clear definition, data source, reporting period and limitations.</p>\n</blockquote>"},{"t":"9.4 Certificate requirements","h":"<ul>\n<li><p>Learner identity and programme title.</p></li>\n<li><p>Modules completed and assessment status.</p></li>\n<li><p>Issue date and unique certificate reference.</p></li>\n<li><p>Issuer / trainer details and verification method.</p></li>\n<li><p>Clear statement of the certificate's scope; do not imply a statutory or professional licence unless authorised.</p></li>\n</ul>"}]},"10":{"title":"HR Metrics, Dashboards and Analytics","intro":"<table>\n\n<thead>\n<tr>\n<th><strong>Metric</strong></th>\n<th><strong>Basic definition</strong></th>\n<th><strong>Interpretation caution</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Headcount</td>\n<td>Number of active employees at a defined point in time.</td>\n<td>Define active status and treatment of contractors / interns.</td>\n</tr>\n<tr>\n<td>Turnover rate</td>\n<td>Separations during period divided by an agreed average headcount, multiplied by 100.</td>\n<td>Define included separation types and average headcount method.</td>\n</tr>\n<tr>\n<td>Time to fill</td>\n<td>Elapsed time from approved requisition opening to accepted offer or another defined milestone.</td>\n<td>State start and end events consistently.</td>\n</tr>\n<tr>\n<td>Offer acceptance rate</td>\n<td>Accepted offers divided by offers made, multiplied by 100.</td>\n<td>Define withdrawn, expired and revised offers.</td>\n</tr>\n<tr>\n<td>Absence rate</td>\n<td>Absence hours or days divided by scheduled hours or days, multiplied by 100.</td>\n<td>Define absence categories and exclusions.</td>\n</tr>\n<tr>\n<td>Training completion</td>\n<td>Learners completing a course divided by learners enrolled or assigned.</td>\n<td>Define completion and treatment of withdrawals.</td>\n</tr>\n<tr>\n<td>Payroll accuracy</td>\n<td>Correct payroll records divided by total payroll records checked, multiplied by 100.</td>\n<td>Define error severity and sampling method.</td>\n</tr>\n<tr>\n<td>Internal fill rate</td>\n<td>Roles filled internally divided by total roles filled, multiplied by 100.</td>\n<td>Define internal moves and role population.</td>\n</tr>\n</tbody>\n</table>","subs":[{"t":"10.1 Dashboard pages","h":"<ul>\n<li><p>HR executive overview: headcount, hiring, turnover, labour cost and priority risks.</p></li>\n<li><p>Recruitment dashboard: vacancies, funnel conversion, source, ageing and offer acceptance.</p></li>\n<li><p>Attendance dashboard: absence, leave, overtime and exceptions.</p></li>\n<li><p>Learning dashboard: enrolment, completion, assessment and skill gaps.</p></li>\n<li><p>Performance dashboard: goal progress, review completion and development actions.</p></li>\n<li><p>Employee experience dashboard: survey themes, case trends and action completion.</p></li>\n<li><p>Compliance dashboard: applicability, owner, due date, status and evidence.</p></li>\n</ul>"},{"t":"10.2 Data governance checklist","h":"<ul>\n<li><p>Document data definitions and source systems.</p></li>\n<li><p>Assign a data owner and authorised users.</p></li>\n<li><p>Use synthetic or anonymised information for training and product demos.</p></li>\n<li><p>Validate missing values, duplicates, date ranges and outliers.</p></li>\n<li><p>Apply least-privilege access and secure export controls.</p></li>\n<li><p>Avoid sensitive profiling and unsupported predictions.</p></li>\n<li><p>Record refresh dates and known limitations.</p></li>\n</ul>"}]},"11":{"title":"Texora AI Product Demonstration Plan","intro":"<p>This section connects HR learning to Texora AI without assuming that every HR function is available in the product. The training site should distinguish: (A) verified live capabilities, (B) recorded demonstrations supplied by the product team, and (C) conceptual workflow examples that are not live integrations.</p>","subs":[{"t":"11.1 Demo experience structure","h":"<ol type=\"1\">\n<li><p>Product overview: explain the problem the product is designed to solve.</p></li>\n<li><p>Sign-up and login: demonstrate the actual current user journey.</p></li>\n<li><p>Role and workspace setup: show only the configuration available in the live environment.</p></li>\n<li><p>Workflow walkthrough: use a synthetic candidate or employee record.</p></li>\n<li><p>AI explanation: describe inputs, outputs, limitations and human review.</p></li>\n<li><p>Reports and dashboard: show real available outputs and their definitions.</p></li>\n<li><p>Security and permissions: explain access controls based on verified product configuration.</p></li>\n<li><p>Help and next steps: show support, contact or product enquiry route.</p></li>\n</ol>"},{"t":"11.2 Suggested demo video catalogue","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Video</strong></th>\n<th><strong>Narration / demonstration outline</strong></th>\n<th><strong>Evidence required</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>01. Product introduction</td>\n<td>What Texora AI does, target users, key use cases and product boundaries.</td>\n<td>Approved product overview and current screenshots.</td>\n</tr>\n<tr>\n<td>02. Sign up and login</td>\n<td>Open official page, register using a test account, verify email / login and explain navigation.</td>\n<td>Working demo account and current UI.</td>\n</tr>\n<tr>\n<td>03. Create a job</td>\n<td>Open the relevant job workflow, enter role details, review and publish or save.</td>\n<td>Verified job creation capability.</td>\n</tr>\n<tr>\n<td>04. Add candidate data</td>\n<td>Use a synthetic candidate profile and show the permitted upload / entry workflow.</td>\n<td>Verified candidate intake capability and privacy approval.</td>\n</tr>\n<tr>\n<td>05. AI screening</td>\n<td>Explain the supported matching or screening output and human review requirement.</td>\n<td>Verified feature, sample output and limitations.</td>\n</tr>\n<tr>\n<td>06. Interview workflow</td>\n<td>Show scheduling, interview stages or evaluation only if supported.</td>\n<td>Verified workflow and test records.</td>\n</tr>\n<tr>\n<td>07. Review and reporting</td>\n<td>Open available reports, explain metrics and export controls.</td>\n<td>Current reporting screens and metric definitions.</td>\n</tr>\n<tr>\n<td>08. Admin and permissions</td>\n<td>Show roles, access and workspace settings if available.</td>\n<td>Verified permissions and admin account.</td>\n</tr>\n<tr>\n<td>09. HR Sales: requirement to proposal</td>\n<td>Show client requirement capture, candidate search against it, fulfilment tracking and a costing proposal, if supported.</td>\n<td>Verified HR Sales module capability, synthetic client and candidate data, approved pricing examples.</td>\n</tr>\n</tbody>\n</table>"},{"t":"11.3 HR-to-product mapping — verification matrix","h":"<table>\n\n<thead>\n<tr>\n<th><strong>HR learning area</strong></th>\n<th><strong>Potential product relevance</strong></th>\n<th><strong>Before publishing</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Recruitment and sourcing</td>\n<td>Candidate / job workflow may be relevant.</td>\n<td>Confirm job posting, candidate intake and ATS features.</td>\n</tr>\n<tr>\n<td>Resume screening</td>\n<td>AI matching or screening may be relevant.</td>\n<td>Confirm supported file types, scoring logic, limitations and human review.</td>\n</tr>\n<tr>\n<td>Interview management</td>\n<td>Interview workflow or interview-related tools may be relevant.</td>\n<td>Confirm scheduling, recording, evaluation and consent requirements.</td>\n</tr>\n<tr>\n<td>Candidate communication</td>\n<td>CX / communication tools may be relevant.</td>\n<td>Confirm channels, templates, integrations and opt-in rules.</td>\n</tr>\n<tr>\n<td>HR operations</td>\n<td>Workflow automation may be relevant.</td>\n<td>Confirm employee record, service request and task features.</td>\n</tr>\n<tr>\n<td>Payroll and attendance</td>\n<td>Do not assume availability.</td>\n<td>Verify dedicated HRMS / payroll integration or present as out of scope.</td>\n</tr>\n<tr>\n<td>Learning and performance</td>\n<td>May be supported by separate tools or integrations.</td>\n<td>Verify LMS, performance and employee development features.</td>\n</tr>\n<tr>\n<td>Compliance and statutory filing</td>\n<td>Do not assume legal compliance functionality.</td>\n<td>Use qualified specialists and verified systems.</td>\n</tr>\n<tr>\n<td>Client hiring requirements, candidate search and costing proposals (HR Sales)</td>\n<td>HR Sales module is under development; requirement, search, fulfilment and proposal features may be relevant.</td>\n<td>Confirm which features are live, how costing is calculated, data-privacy controls and approval workflow before demonstrating.</td>\n</tr>\n</tbody>\n</table>"},{"t":"11.4 Demo production standards","h":"<ul>\n<li><p>Record in a dedicated test environment, never with real employee or candidate personal data.</p></li>\n<li><p>Use fictional names, emails, phone numbers and resumes.</p></li>\n<li><p>Show the actual product UI; label mockups and concept screens clearly.</p></li>\n<li><p>Keep each video focused on one user task and one outcome.</p></li>\n<li><p>Add captions, readable zoom, narration and a short recap.</p></li>\n<li><p>Show AI outputs as decision support, not as final employment decisions.</p></li>\n<li><p>Disclose known limitations and manual steps.</p></li>\n<li><p>Re-record when the product UI or feature changes.</p></li>\n<li><p>Obtain approval from the product owner before publishing screenshots, logos or claims.</p></li>\n</ul>"},{"t":"11.5 Suggested video script format","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Part</strong></th>\n<th><strong>Narration</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Opening</td>\n<td>In this video, we will demonstrate [specific task] in the current Texora AI product.</td>\n</tr>\n<tr>\n<td>Context</td>\n<td>This task helps [user role] complete [business problem].</td>\n</tr>\n<tr>\n<td>Action</td>\n<td>First, open [verified screen]. Enter [synthetic example data].</td>\n</tr>\n<tr>\n<td>Review</td>\n<td>Check [output / status] and explain what it means.</td>\n</tr>\n<tr>\n<td>Human control</td>\n<td>A responsible user must review the result and make the final decision where required.</td>\n</tr>\n<tr>\n<td>Close</td>\n<td>We have completed [task]. In the next lesson, we will explore [next verified task].</td>\n</tr>\n</tbody>\n</table>"}]},"13":{"title":"Roles, Governance, Privacy and Quality Assurance","intro":"","subs":[{"t":"13.1 Suggested platform roles","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Role</strong></th>\n<th><strong>Responsibilities</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Learner</td>\n<td>Access lessons, complete activities, take assessments and manage own progress.</td>\n</tr>\n<tr>\n<td>Trainer</td>\n<td>Deliver sessions, review assignments, provide feedback and manage cohorts.</td>\n</tr>\n<tr>\n<td>Content editor</td>\n<td>Create and update lessons, videos, templates and glossary entries.</td>\n</tr>\n<tr>\n<td>HR subject-matter expert</td>\n<td>Validate process accuracy and practical relevance.</td>\n</tr>\n<tr>\n<td>Legal / compliance reviewer</td>\n<td>Verify legal statements, applicability, forms, rates and effective dates.</td>\n</tr>\n<tr>\n<td>Product owner</td>\n<td>Verify Texora product capabilities, screenshots, claims and demo accounts.</td>\n</tr>\n<tr>\n<td>Administrator</td>\n<td>Manage users, roles, content publishing and platform configuration.</td>\n</tr>\n</tbody>\n</table>"},{"t":"13.2 Privacy and security requirements","h":"<ul>\n<li><p>Collect only data needed for learning or service delivery.</p></li>\n<li><p>Publish a clear privacy notice and retention policy.</p></li>\n<li><p>Use synthetic data in training examples and product demos.</p></li>\n<li><p>Restrict access to employee, candidate, payroll and grievance information.</p></li>\n<li><p>Do not place passwords, identity documents or sensitive employee records in public demo environments.</p></li>\n<li><p>Use secure authentication, encryption in transit and appropriate storage controls.</p></li>\n<li><p>Maintain audit logs for privileged actions and sensitive record access.</p></li>\n<li><p>Define incident reporting and data deletion processes.</p></li>\n<li><p>Review third-party tools, integrations and data processing before use.</p></li>\n</ul>"},{"t":"13.3 Content quality assurance","h":"<table>\n\n<thead>\n<tr>\n<th><strong>Review area</strong></th>\n<th><strong>Reviewer</strong></th>\n<th><strong>Acceptance criteria</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>HR process accuracy</td>\n<td>HR subject-matter expert</td>\n<td>Steps, roles, outputs and exceptions are realistic.</td>\n</tr>\n<tr>\n<td>Legal accuracy</td>\n<td>Qualified legal / compliance reviewer</td>\n<td>Current law, applicability, dates and claims are verified.</td>\n</tr>\n<tr>\n<td>Payroll accuracy</td>\n<td>Payroll specialist</td>\n<td>Calculations and statutory inputs are validated.</td>\n</tr>\n<tr>\n<td>Product accuracy</td>\n<td>Texora product owner</td>\n<td>Screenshots and capability claims match the current product.</td>\n</tr>\n<tr>\n<td>Learning quality</td>\n<td>Instructional designer / trainer</td>\n<td>Objectives, examples, practice and assessment align.</td>\n</tr>\n<tr>\n<td>Accessibility</td>\n<td>QA / accessibility reviewer</td>\n<td>Keyboard, contrast, captions and semantic structure are checked.</td>\n</tr>\n<tr>\n<td>Technical quality</td>\n<td>Engineering / QA</td>\n<td>Links, downloads, forms, progress and mobile layouts work.</td>\n</tr>\n</tbody>\n</table>"}]}},"gl":[["ATS","Applicant Tracking System; software used to manage recruitment stages and candidate records."],["HRIS","Human Resource Information System; software that stores and manages HR data and processes."],["CTC","Cost to Company; the employer's overall annual cost associated with an employee."],["Gross Salary","Earnings before employee-side deductions."],["Net Salary","Amount payable after applicable deductions."],["KRA","Key Result Area; an important area of responsibility."],["KPI","Key Performance Indicator; a defined measure used to track performance or outcomes."],["OKR","Objectives and Key Results; a goal-setting framework linking objectives to measurable results."],["TNA","Training Needs Analysis; process of identifying capability gaps and learning needs."],["EVP","Employee Value Proposition; the value and experience an organisation offers employees."],["FnF","Full and Final Settlement; reconciliation of amounts due and recoverable at separation."],["PIP","Performance Improvement Plan; a structured plan to address documented performance gaps."],["SLA","Service Level Agreement; a defined service target or commitment."],["Mandate","A hiring requirement a client gives to a recruitment or staffing firm to fulfil."],["Requirement fulfilment","Delivering suitable candidates against a client requirement through to selection, offer and joining."],["Contingency fee","A fee payable to the recruitment firm only when a candidate is successfully hired."],["Retainer","An advance or recurring fee paid to secure dedicated search effort before or during delivery."],["Placement fee","The fee charged for a successful hire, often calculated as a percentage of the candidate’s annual CTC."],["Verified profile","A candidate profile whose identity, interest, availability and key details have been checked and consent to share obtained."],["TAT","Turnaround Time; the agreed time to complete a step such as submitting profiles against a requirement."],["Replacement guarantee","Agreed terms under which the recruitment firm finds a replacement if a placed candidate leaves within a defined period."],["RPO","Recruitment Process Outsourcing; a model where a provider manages all or part of a client’s recruitment process."],["Markup","The percentage or amount added to employment cost in contract staffing to cover the provider’s management fee."],["DEI","Diversity, Equity and Inclusion."],["POSH","Prevention of Sexual Harassment; in India, commonly refers to the workplace sexual-harassment prevention framework and applicable law."],["Compa-ratio","An employee's pay compared with the midpoint of the relevant salary range."],["Attrition","Employee exits over a defined period, measured using a stated method."],["Headcount","Number of employees in a defined population at a specific point in time."],["Probation","An initial employment period governed by applicable contract, policy and law."],["Succession Planning","Preparing for continuity in critical roles by identifying and developing potential successors."],["Employee Lifecycle","The stages an employee moves through from workforce planning and attraction to exit."],["Maker-checker","A control where one person prepares a transaction and another authorised person reviews it."]],"qz":[{"c":"Recruitment","q":"Which method best supports a consistent interview decision?","a":"A structured interview with job-related questions and a common scoring rubric."},{"c":"Onboarding","q":"Which teams should coordinate first-day readiness?","a":"HR, the hiring manager, IT and facilities, as relevant."},{"c":"HR Operations","q":"Why restrict access to personnel records?","a":"To protect employee privacy and limit access to authorised business needs."},{"c":"Attendance","q":"What should happen when an attendance record is disputed?","a":"Validate evidence, follow the correction process and retain the approval trail."},{"c":"Payroll","q":"What should be done before releasing payroll?","a":"Validate inputs, review exceptions, obtain approval and reconcile outputs."},{"c":"Performance","q":"What makes a performance goal useful?","a":"A clear outcome, measure, owner, timeframe and agreed expectations."},{"c":"Learning","q":"What does Training Needs Analysis identify?","a":"The gap between current capability and required capability."},{"c":"Employee Relations","q":"What is important in a grievance investigation?","a":"Impartiality, confidentiality, evidence, fairness and appropriate escalation."},{"c":"Compliance","q":"What if legal applicability is unclear?","a":"Obtain qualified legal/compliance review and document the verified decision."},{"c":"Analytics","q":"What should accompany a dashboard metric?","a":"A clear definition, data source, reporting period and limitations."}],"rm":[{"t":"Stage 1 — HR Foundations (Weeks 1–6)","w":[{"w":1,"t":"HR fundamentals, employee lifecycle and HR operating model","m":[]},{"w":2,"t":"Module 01 Recruitment &amp; Talent Acquisition","m":[1]},{"w":3,"t":"Module 02 Onboarding &amp; Induction","m":[2]},{"w":4,"t":"Module 03 HR Operations","m":[3]},{"w":5,"t":"Module 04 Attendance &amp; Leave","m":[4]},{"w":6,"t":"Module 11 HR Policies &amp; Documentation","m":[11]}]},{"t":"Stage 2 — Rewards and Governance (Weeks 7–12)","w":[{"w":7,"t":"Module 05 Payroll Management","m":[5]},{"w":8,"t":"Module 06 Compensation &amp; Benefits","m":[6]},{"w":9,"t":"Module 10 Labour Law &amp; Compliance","m":[10]},{"w":10,"t":"Payroll and compliance case study","m":[]},{"w":11,"t":"Module 20 Exit &amp; Offboarding","m":[20]},{"w":12,"t":"Stage assessment and portfolio review","m":[]}]},{"t":"Stage 3 — People Growth and Experience (Weeks 13–18)","w":[{"w":13,"t":"Module 07 Performance Management","m":[7]},{"w":14,"t":"Module 08 Learning &amp; Development","m":[8]},{"w":15,"t":"Module 14 Talent Management","m":[14]},{"w":16,"t":"Module 15 Career &amp; Succession Planning","m":[15]},{"w":17,"t":"Module 16 Employee Engagement &amp; Culture","m":[16]},{"w":18,"t":"Modules 09 Employee Relations and 17 DEI","m":[9,17]}]},{"t":"Stage 4 — Strategy, Data and Application (Weeks 19–24)","w":[{"w":19,"t":"Module 18 Health, Safety &amp; Wellbeing","m":[18]},{"w":20,"t":"Modules 19 Employer Branding and 21 HR Sales &amp; Client Hiring Solutions","m":[19,21]},{"w":21,"t":"Module 12 HR Analytics &amp; HRIS","m":[12]},{"w":22,"t":"Module 13 Workforce Planning","m":[13]},{"w":23,"t":"Integrated capstone and Texora AI product demonstrations","m":[]},{"w":24,"t":"Final assessment, presentation and portfolio submission","m":[]}]}],"tpl":[{"c":"Recruitment","i":["Manpower requisition form","Job description template","Candidate sourcing tracker","Resume screening scorecard","Interview evaluation sheet","Reference check checklist","Offer approval checklist"]},{"c":"Onboarding","i":["Pre-joining checklist","Joining form","Employee document checklist","Induction agenda","IT asset issue form","Policy acknowledgement","30-60-90 day plan"]},{"c":"HR Operations","i":["Employee master data form","Employee change request","HR helpdesk request form","Personnel file index","Employee letter request","Records retention schedule"]},{"c":"Attendance and Leave","i":["Monthly shift roster","Leave application form","Leave balance register","Attendance correction form","Overtime approval form","Monthly attendance reconciliation"]},{"c":"Payroll and Rewards","i":["Payroll input sheet","Salary structure worksheet","Payroll variance report","Increment recommendation","Benefits enrolment checklist","Payroll approval checklist"]},{"c":"Performance and Learning","i":["Goal-setting form","KRA/KPI sheet","Performance review form","PIP template","Training needs analysis","Training calendar","Training evaluation form"]},{"c":"Employee Relations and Compliance","i":["Grievance intake form","Investigation plan","Evidence log","Compliance applicability matrix","Compliance calendar","Audit checklist","Corrective action register"]},{"c":"Policies and Engagement","i":["Policy template","SOP template","Employee handbook outline","Engagement survey","Stay interview guide","Recognition nomination form"]},{"c":"Talent and Career","i":["Skills matrix","Competency framework","Individual development plan","Talent review template","Succession matrix","Career conversation guide"]},{"c":"Exit","i":["Resignation acknowledgement","Notice period tracker","Knowledge transfer checklist","Asset clearance form","Exit interview form","Full-and-final input checklist"]},{"c":"HR Sales and Client Hiring","i":["Client requirement intake form","Hiring brief and requirement confirmation note","Candidate submission format","Requirement fulfilment tracker","Costing calculator","Client proposal and quotation template","Invoice handover note"]}],"meta":"Every downloadable template should include: template name, purpose, owner, version, effective date, review date, instructions, required fields, approval fields, confidentiality label and a note describing whether legal or specialist review is required."};

